import threading as _threading_hg

if not getattr(st, "_decide_heading_guard", False):
    # Wrap st.markdown/subheader/header/title ONCE so a panel body that prints its own
    # title can be detected (thread-local, so several windows never interfere).
    st._decide_heading_guard = True
    st._decide_hg_state = _threading_hg.local()

    def _decide_install_heading_guard(_name: str) -> None:
        _orig = getattr(st, _name)

        def _wrapped(*args, **kwargs):
            _state = getattr(st._decide_hg_state, "titles", None)
            if _state is not None and not _state["seen"]:
                _body = args[0] if args else kwargs.get("body")
                _text = str(_body) if _body is not None else ""
                if _name != "markdown" or _text.lstrip().startswith("#"):
                    _words = set(_re_hg.findall(r"[a-z0-9]{3,}", _text.lower()))
                    if _words & _state["words"]:
                        _state["seen"] = True
            return _orig(*args, **kwargs)

        setattr(st, _name, _wrapped)

    for _n in ("markdown", "subheader", "header", "title"):
        _decide_install_heading_guard(_n)


STAGING_BUILD_TAG = "staging-3"



def _rename_epoch_suffix() -> str:
    """"" until the first rename in this session, then "_e<n>". Every
    rename bumps the counter (see _commit_identifier_rename) and the
    editor-row widget keys below carry it, so the browser sees BRAND NEW
    widgets whose text comes from the already-rewritten document. Deleting
    a widget's server-side state is not enough: Streamlit's frontend keeps
    its own copy of a keyed text_input's last value and would send the old
    text back on the next interaction, silently undoing the rename inside
    that box (e.g. a Variable's Definition)."""

    try:
        epoch = int(st.session_state.get("_rename_epoch", 0))
    except Exception:
        epoch = 0
    return f"_e{epoch}" if epoch else ""


def editor_row_key(prefix: str, row: dict[str, Any]) -> str:
    return _base_editor_row_key(prefix, row) + _rename_epoch_suffix()


def _staging_config() -> tuple[set[str] | None, str]:
    """Staging switch -> (allowed model types or None for all, where it came from).
    Order: env var / Streamlit secret DECIDE_STAGING_MODELS (e.g. "tree,markov";
    "all" = no restriction), then the STAGING_MODELS file next to this script
    (committed on the staging branch, so no secret is needed on the server).
    Nothing set = every model type (normal development behaviour)."""
    raw = os.environ.get("DECIDE_STAGING_MODELS")
    source = "env"
    if not raw:
        try:
            raw = st.secrets.get("DECIDE_STAGING_MODELS")
        except Exception:  # noqa: BLE001 - no secrets file locally
            raw = None
        source = "secret"
    if not raw:
        try:
            raw = (Path(__file__).resolve().parent / "STAGING_MODELS").read_text(encoding="utf-8")
        except OSError:
            raw = None
        source = "file"
    if not raw or not str(raw).strip():
        return None, "none"
    parts = {part.strip().lower() for part in str(raw).replace("\n", ",").split(",") if part.strip()}
    if parts & {"all", "*"}:
        return None, source + ":all"
    return parts, source


def _staging_allowed_models() -> set[str] | None:
    return _staging_config()[0]


