# ---------------------------------------------------------------------------
# Optional editors: modules in the "optional_editors" folder, when present, add an editor
# (picker card, files, reset, report, translations) without app.py knowing about them.
# ---------------------------------------------------------------------------
_OPTIONAL_EDITORS: dict[str, dict[str, Any]] = {}


def _optional_session_defaults() -> dict[str, Any]:
    out: dict[str, Any] = {}
    for entry in _OPTIONAL_EDITORS.values():
        out.update(entry.get("session_defaults") or {})
    return out


def _with_optional_translations(base: dict[str, str], language: str) -> dict[str, str]:
    merged = dict(base)
    for entry in _OPTIONAL_EDITORS.values():
        translations = entry.get("translations") or {}
        merged.update(translations.get("en", {}))
        merged.update(translations.get(language, {}))
    return merged


def _load_optional_editors() -> None:
    folder = Path(__file__).resolve().parent / "optional_editors"
    if _OPTIONAL_EDITORS or not folder.is_dir():
        return
    import importlib.util

    for path in sorted(folder.glob("*.py")):
        if path.name.startswith("_"):
            continue
        try:
            spec = importlib.util.spec_from_file_location(f"optional_editor_{path.stem}", path)
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)
            entry = module.register(globals())
        except Exception:  # noqa: BLE001 - an optional editor that cannot load is simply not offered
            continue
        if entry:
            _OPTIONAL_EDITORS[entry["kind"]] = entry
            _CLEAR_MODEL_HANDLERS[entry["kind"]] = entry["clear_model"]


