def _migrate_markov_document(document: dict[str, Any]) -> dict[str, Any]:
    """In-place-compatible migration: wrap an old flat, single-model
    Markov document (states/transitions at the top level, as every
    document saved before the multi-strategy feature looked) into the new
    "strategies" shape. A document that already has a non-empty
    "strategies" list is left untouched, so this is safe to call on every
    document load."""

    strategies = document.get("strategies")
    if isinstance(strategies, list) and strategies:
        return document
    legacy_states = document.pop("states", None)
    legacy_transitions = document.pop("transitions", None)
    document["strategies"] = [
        {
            "id": "strategy_1",
            "name": document.get("name") or "Strategy 1",
            "states": legacy_states if legacy_states is not None else [],
            "transitions": legacy_transitions if legacy_transitions is not None else [],
        }
    ]
    return document

