# Parameter-key renames for distributions whose keys used to be generic
# letters/Greek names but now use their standard flexsurv/R names (Weibull
# a/b -> shape/scale, Lognormal mu/sigma -> meanlog/sdlog, Exponential
# lambda -> rate). Keeps documents saved before this rename working: the
# old key's value is carried over to the new key the first time that
# distribution row is loaded, instead of showing an empty input box.
LEGACY_DISTRIBUTION_PARAMETER_KEYS: dict[str, dict[str, str]] = {
    "Weibull": {"a": "shape", "b": "scale"},
    "Lognormal": {"mu": "meanlog", "sigma": "sdlog"},
    "Exponential": {"lambda": "rate"},
}


def migrate_legacy_distribution_parameters(distribution_type: str, parameters: dict[str, Any]) -> None:
    """Move any old-named keys in ``parameters`` to their current name, in place."""

    for old_key, new_key in LEGACY_DISTRIBUTION_PARAMETER_KEYS.get(distribution_type, {}).items():
        if old_key in parameters and new_key not in parameters:
            parameters[new_key] = parameters.pop(old_key)
    if distribution_type == "Gamma":
        # Gamma follows the flexsurv convention (shape, rate): older documents
        # stored k (shape) and theta (SCALE), so theta becomes rate = 1/theta.
        from heor_tree_engine.distributions import migrate_legacy_gamma_parameters

        migrate_legacy_gamma_parameters(parameters)

