# --------------------------------------------------------------------------
# Tree Editor: autosave, "unsaved changes" warning and restore (same idea as
# the NMA editor's autosave -- see nma_editor_support.autosave_*).
# --------------------------------------------------------------------------

TREE_AUTOSAVE_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "autosave")
TREE_AUTOSAVE_FILE = os.path.join(TREE_AUTOSAVE_DIR, "tree-autosave.json")
TREE_AUTOSAVE_KEEP = 5  # numbered backups tree-autosave-1.json (newest) ... -5


def _tree_fingerprint(document: dict[str, Any]) -> str:
    return hashlib.md5(
        json.dumps(document, sort_keys=True, ensure_ascii=False, default=str).encode("utf-8")
    ).hexdigest()


def _memo_export_code(slot: str, source: Any, language: str, build) -> str:
    """Reuse the generated export code while the model and language are
    unchanged (the sidebar used to regenerate it on every rerun). Exceptions
    propagate exactly as before and are not cached."""

    key = (language, _tree_fingerprint(source) if isinstance(source, dict) else repr(source))
    cache = st.session_state.get("_export_code_memo")
    if not isinstance(cache, dict):
        cache = st.session_state["_export_code_memo"] = {}
    hit = cache.get(slot)
    if hit is not None and hit[0] == key:
        return hit[1]
    text = build()
    cache[slot] = (key, text)
    return text


def _tree_autosave_write(document: dict[str, Any]) -> None:
    """Write the model (exactly what Save would download) to autosave/,
    rotating the previous copies. Best effort: never raises."""

    import datetime

    try:
        os.makedirs(TREE_AUTOSAVE_DIR, exist_ok=True)
        if os.path.exists(TREE_AUTOSAVE_FILE):
            for index in range(TREE_AUTOSAVE_KEEP - 1, 0, -1):
                older = os.path.join(TREE_AUTOSAVE_DIR, f"tree-autosave-{index}.json")
                if os.path.exists(older):
                    shutil.move(older, os.path.join(TREE_AUTOSAVE_DIR, f"tree-autosave-{index + 1}.json"))
            shutil.move(TREE_AUTOSAVE_FILE, os.path.join(TREE_AUTOSAVE_DIR, "tree-autosave-1.json"))
        payload = {**document, "autosaved_at": datetime.datetime.now().isoformat(timespec="seconds")}
        tmp = TREE_AUTOSAVE_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=1)
        os.replace(tmp, TREE_AUTOSAVE_FILE)
    except OSError:
        pass


def _tree_autosave_read() -> dict[str, Any] | None:
    try:
        with open(TREE_AUTOSAVE_FILE, encoding="utf-8") as handle:
            data = json.load(handle)
        return data if isinstance(data, dict) and data.get("nodes") and data.get("root_id") else None
    except (OSError, ValueError):
        return None


def _tree_autosave_discard() -> None:
    try:
        if os.path.exists(TREE_AUTOSAVE_FILE):
            os.replace(TREE_AUTOSAVE_FILE, os.path.join(TREE_AUTOSAVE_DIR, "tree-autosave-discarded.json"))
    except OSError:
        pass


_TREE_START_FP: list[str] = []


def _tree_is_untouched_example(document: dict[str, Any]) -> bool:
    if not _TREE_START_FP:
        _TREE_START_FP.append(_tree_fingerprint(TREE_START_DOCUMENT))
    return _tree_fingerprint(document) == _TREE_START_FP[0]


def _tree_autosave_step(document: dict[str, Any]) -> None:
    """Called every run: autosave when the model changed since the last
    write (skipped while the untouched example is shown), and show the
    "Autosaved HH:MM:SS" status line."""

    import datetime

    fingerprint = _tree_fingerprint(document)
    if st.session_state.get("tree_autosave_fp") != fingerprint:
        st.session_state.tree_autosave_fp = fingerprint
        if not _tree_is_untouched_example(document):
            _tree_autosave_write(document)
            st.session_state.tree_autosave_time = datetime.datetime.now().strftime("%H:%M:%S")
    if st.session_state.get("tree_autosave_time"):
        st.caption(
            f"Autosaved {st.session_state.tree_autosave_time} (autosave/tree-autosave.json)"
        )


def _tree_unsaved_warning(document: dict[str, Any]) -> None:
    """Prominent warning while the model differs from the last file the user
    downloaded / opened (a browser download can't be detected any other
    way than the download button's own click)."""

    saved_fp = st.session_state.setdefault("tree_saved_fp", _tree_fingerprint(TREE_START_DOCUMENT))
    if _tree_fingerprint(document) != saved_fp:
        st.warning(
            "**Unsaved changes.** Your model has changed since it was last saved or opened. "
            "Click **Save** in the File panel to download it. An automatic backup is kept in the "
            "autosave folder, but it is not a substitute for saving.",
            icon=":material/warning:",
        )


def _tree_offer_autosave_restore() -> None:
    """Once per session: if an autosave from an earlier session exists,
    remember it so the restore banner can offer it."""

    if st.session_state.get("tree_autosave_checked"):
        return
    st.session_state.tree_autosave_checked = True
    data = _tree_autosave_read()
    if data and _tree_fingerprint({k: v for k, v in data.items() if k != "autosaved_at"}) != _tree_fingerprint(TREE_START_DOCUMENT):
        st.session_state.tree_autosave_pending = data


def _render_tree_autosave_banner() -> None:
    data = st.session_state.get("tree_autosave_pending")
    if not data:
        return
    when = str(data.get("autosaved_at", "")).replace("T", " ")
    strategies = 0
    for node in data.get("nodes", []):
        if node.get("id") == data.get("root_id"):
            strategies = len(node.get("branches", []))
    with st.container(border=True, key="tree_autosave_banner"):
        st.markdown(
            f"**:material/restore: Unsaved work from the last session was found** \u00b7 {when} \u00b7 "
            f"{len(data.get('nodes', []))} nodes, {strategies} strategies"
        )
        restore_col, discard_col, _ = st.columns([1, 1, 3])
        with restore_col:
            if st.button("Restore", type="primary", icon=":material/restore:", key="tree_autosave_restore",
                         use_container_width=True):
                restored = {k: v for k, v in data.items() if k != "autosaved_at"}
                st.session_state.document = restored
                st.session_state.positions = {}
                st.session_state.selected_id = restored.get("root_id")
                st.session_state.flow_timestamp += 1
                st.session_state.flow_fitted = False
                st.session_state.flow_component_version += 1
                st.session_state.pop("tree_path_results", None)
                st.session_state.tree_autosave_pending = None
                st.session_state.tree_autosave_fp = _tree_fingerprint(restored)
                st.session_state.tree_current_path = None
                # Restored work is unsaved by definition: keep the warning up
                # until the user downloads it.
                st.session_state.tree_saved_fp = "__restored_unsaved__"
                auto_layout()
                st.rerun()
        with discard_col:
            if st.button("Discard", icon=":material/delete:", key="tree_autosave_discard",
                         use_container_width=True):
                _tree_autosave_discard()
                st.session_state.tree_autosave_pending = None
                st.rerun()


# --------------------------------------------------------------------------
# Tree Editor: Save / Save as / Open write to and read from disk directly (the
# app runs on the user's own machine), like an ordinary desktop app: Save
# overwrites the current file, Save as writes a new one.
# --------------------------------------------------------------------------

TREE_SETTINGS_FILE = os.path.join(TREE_AUTOSAVE_DIR, "tree-settings.json")
TREE_DEFAULT_MODELS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "models")


def _tree_models_dir() -> str:
    """Folder Save as / Open use: last choice (remembered in
    autosave/tree-settings.json), else models/ next to the app."""

    if st.session_state.get("tree_models_dir"):
        return st.session_state.tree_models_dir
    try:
        with open(TREE_SETTINGS_FILE, encoding="utf-8") as handle:
            saved = json.load(handle).get("models_dir")
        if saved:
            return str(saved)
    except (OSError, ValueError, AttributeError):
        pass
    return TREE_DEFAULT_MODELS_DIR


def _tree_remember_models_dir(folder: str) -> None:
    st.session_state.tree_models_dir = folder
    try:
        os.makedirs(TREE_AUTOSAVE_DIR, exist_ok=True)
        with open(TREE_SETTINGS_FILE, "w", encoding="utf-8") as handle:
            json.dump({"models_dir": folder}, handle)
    except OSError:
        pass


def _tree_safe_filename(name: str) -> str:
    base = os.path.basename((name or "").strip().replace("\\", "/")) or "decision-tree.decide"
    base = re.sub(r'[<>:"|?*\x00-\x1f]', "_", base)
    if base.lower().endswith(".decide"):
        return base
    if base.lower().endswith(".json"):
        base = base[: -len(".json")]
    return base + ".decide"


def _tree_list_models(folder: str) -> list[str]:
    try:
        names = [n for n in os.listdir(folder) if n.lower().endswith((".decide", ".json")) and not n.startswith(".")]
        return sorted(names, key=lambda n: os.path.getmtime(os.path.join(folder, n)), reverse=True)
    except OSError:
        return []


def _tree_write_model(path: str) -> None:
    """Write the current model to ``path``; records the result for the file
    panel (st.session_state.tree_file_message = (kind, text))."""

    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as handle:
            json.dump(st.session_state.document, handle, indent=2, ensure_ascii=False)
        os.replace(tmp, path)
    except OSError as exc:
        st.session_state.tree_file_message = ("error", f"Could not save to {path}: {exc}")
        return
    st.session_state.tree_current_path = path
    st.session_state.tree_filename_input = os.path.basename(path)
    st.session_state.tree_saved_fp = _tree_fingerprint(st.session_state.document)
    st.session_state.tree_overwrite_pending = None
    st.session_state.tree_file_message = ("success", f"Saved to {path}")


def _tree_target_path() -> str:
    folder = os.path.expanduser((st.session_state.get("tree_models_dir_input") or _tree_models_dir()).strip())
    _tree_remember_models_dir(folder)
    return os.path.join(folder, _tree_safe_filename(st.session_state.get("tree_filename_input", "")))


def _tree_cb_save() -> None:
    """Save: overwrite the current file; a model with no file yet is written
    to <folder>/<filename>, overwriting silently if that name exists."""

    current = st.session_state.get("tree_current_path")
    if current:
        _tree_write_model(current)
        return
    # Like any app's Save: write straight to <folder>/<filename>, overwriting
    # an existing file without asking.
    _tree_write_model(_tree_target_path())


def _tree_cb_confirm_overwrite() -> None:
    pending = st.session_state.get("tree_overwrite_pending")
    if pending:
        _tree_write_model(pending)


def _tree_cb_cancel_overwrite() -> None:
    st.session_state.tree_overwrite_pending = None


def _tree_cb_open_saved() -> None:
    folder = os.path.expanduser((st.session_state.get("tree_models_dir_input") or _tree_models_dir()).strip())
    choice = st.session_state.get("tree_open_choice")
    if not choice:
        return
    path = os.path.join(folder, choice)
    try:
        with open(path, encoding="utf-8") as handle:
            document = json.load(handle)
    except (OSError, ValueError) as exc:
        st.session_state.tree_file_message = ("error", f"Could not open {path}: {exc}")
        return
    if not isinstance(document, dict) or not document.get("nodes") or not document.get("root_id"):
        st.session_state.tree_file_message = ("error", f"{path} is not a Decision Tree model file.")
        return
    _tree_remember_models_dir(folder)
    st.session_state.document = document
    st.session_state.positions = {}
    st.session_state.selected_id = document.get("root_id")
    st.session_state.flow_timestamp += 1
    st.session_state.flow_fitted = False
    st.session_state.flow_component_version += 1
    st.session_state.pop("tree_path_results", None)
    st.session_state.tree_current_path = path
    st.session_state.tree_filename_input = os.path.basename(path)
    st.session_state.tree_saved_fp = _tree_fingerprint(document)
    st.session_state.tree_file_message = ("success", f"Opened {path}")


def _render_tree_save_controls() -> None:
    """File panel: Save (overwrite current file), Save as (new file), and Open
    from the models folder."""

    if DESKTOP_MODE:
        return  # File > Open / Save / Save As live in the native menu bar
    st.session_state.setdefault("tree_filename_input", "decision-tree.decide")
    st.session_state.setdefault("tree_models_dir_input", _tree_models_dir())
    message = st.session_state.pop("tree_file_message", None)
    current = st.session_state.get("tree_current_path")
    st.caption(f"Current file: {current}" if current else "Current file: not saved yet")
    st.button(
        T["save"], type="primary", use_container_width=True, key="tree_save_button",
        icon=":material/save:", on_click=_tree_cb_save,
        help="Overwrites the current file. A new model is saved as <folder>/<file name> below.",
    )
    st.text_input(T["filename"], key="tree_filename_input")
    # Save as = an ordinary browser download: the browser's own dialog lets
    # the user choose the name and folder on their own computer, so this also
    # works when the app runs on a server.
    if st.download_button(
        T["save_as"], json.dumps(st.session_state.document, indent=2, ensure_ascii=False),
        _tree_safe_filename(st.session_state.get("tree_filename_input", "")), "application/json",
        use_container_width=True, key="tree_save_as_button", icon=":material/download:",
        help="Downloads a copy to your computer (choose the name and folder in the browser's save dialog).",
    ):
        st.session_state.tree_saved_fp = _tree_fingerprint(st.session_state.document)
    st.text_input("Folder", key="tree_models_dir_input", help="Where Save as and Open look. Remembered for next time.")
    pending = st.session_state.get("tree_overwrite_pending")
    if pending:
        st.warning(f"{pending} already exists. Overwrite it?")
        confirm_col, cancel_col = st.columns(2)
        with confirm_col:
            st.button("Overwrite", type="primary", use_container_width=True, key="tree_overwrite_confirm",
                      on_click=_tree_cb_confirm_overwrite)
        with cancel_col:
            st.button("Cancel", use_container_width=True, key="tree_overwrite_cancel",
                      on_click=_tree_cb_cancel_overwrite)
    saved_models = _tree_list_models(os.path.expanduser(st.session_state.tree_models_dir_input.strip()))
    if saved_models:
        st.selectbox("Saved models", saved_models, key="tree_open_choice")
        st.button("Open saved model", use_container_width=True, key="tree_open_saved_button",
                  on_click=_tree_cb_open_saved)
    if message:
        kind, text = message
        (st.success if kind == "success" else st.error)(text)


