def edit_selected(
    node: dict[str, Any],
    label: str,
    cost: str,
    effect: str,
) -> None:
    node["id"] = label.strip() or node["id"]
    if node["type"] == "terminal":
        node["cost"] = numeric_or_name(cost)
        node["effect"] = numeric_or_name(effect)
OUTCOME_TYPES = ["cost", "effect", "icer", "nmb", "cer", "nhb"]


def _default_outcome_symbol(outcome_type: str) -> str:
    return {"cost": "$", "effect": "E", "icer": "$/E", "nmb": "$", "cer": "$/E", "nhb": "E"}.get(outcome_type, "")


def _default_outcome_decimals(outcome_type: str) -> int:
    return {"cost": 2, "effect": 4, "icer": 0, "nmb": 0, "cer": 2, "nhb": 4}.get(outcome_type, 2)


def ensure_document_outcomes(document: dict[str, Any]) -> list[dict[str, Any]]:
    """Return document["outcomes"], creating the default 2 rows (Cost,
    Effect) the first time a model is opened, seeded from any
    pre-existing cost_decimals/effect_decimals so older saved models keep
    their exact previous decimal places. The first Cost row (id "cost")
    and first Effect row (id "effect") are always the real primary pair
    already stored in TerminalNode.cost/effect and
    Branch.cost_increment/effect_increment; any further Cost/Effect row
    (id like "cost_2") is a genuinely extra, independently tracked outcome
    -- see Engine.run()'s outcome_kinds and Branch/TerminalNode.extra_outcomes.
    ICER/NMB/CER/NHB rows only control how those already-computed Analysis
    metrics are displayed (never inputs); they are opt-in via the +
    button rather than pre-populated by default."""

    outcomes = document.get("outcomes")
    if not outcomes:
        outcomes = [
            {
                "id": "cost", "type": "cost", "label": "Cost",
                "symbol": document.get("cost_symbol") or "$",
                "decimals": int(document.get("cost_decimals", 2)),
            },
            {
                "id": "effect", "type": "effect", "label": "Effect",
                "symbol": document.get("effect_symbol") or "E",
                "decimals": int(document.get("effect_decimals", 4)),
            },
        ]
        document["outcomes"] = outcomes
    return outcomes


def _format_outcome_value(raw_value: Any, decimals: int) -> str:
    """Format a branch/state Cost or Effect value for canvas display: a
    plain number is shown with the outcome's configured decimal places
    (the Outcomes table's "decimals" column), matching how the Results
    and Analysis sections already format numbers with
    f"{value:.{decimals}f}". A parameter name or formula string
    (NumericRef) is shown exactly as typed, since a decimal count doesn't
    apply to it. None/unset becomes an empty string."""

    if raw_value is None or raw_value == "":
        return ""
    if isinstance(raw_value, bool):
        return str(raw_value)
    if isinstance(raw_value, (int, float)):
        return f"{float(raw_value):.{decimals}f}"
    return str(raw_value)


def _next_outcome_id(existing_ids: set[str], outcome_type: str) -> str:
    suffix = 2
    candidate = f"{outcome_type}_{suffix}"
    while candidate in existing_ids:
        suffix += 1
        candidate = f"{outcome_type}_{suffix}"
    return candidate


def outcome_rows_by_type(document: dict[str, Any], outcome_type: str) -> list[dict[str, Any]]:
    """Every outcome row of one type (e.g. every Cost row), in table order."""

    return [row for row in ensure_document_outcomes(document) if row.get("type") == outcome_type]


def _tree_disable_effect(document: dict[str, Any]) -> None:
    """Cost-only mode (Tree Editor): the user deleted the primary Effect
    row from the Outcomes table. Back up every primary effect value
    (branch effect_increment, terminal effect) into
    document["effect_backup"], then zero them so canvas, Run, Analysis and
    SA/PSA all see no effect. _tree_restore_effect() undoes this if an
    Effect row is added back. Extra Effect outcomes are separate rows and
    are untouched."""

    backup: dict[str, Any] = {"branches": {}, "terminals": {}}
    for node in document.get("nodes", []):
        node_id = node.get("id")
        if node.get("type") == "terminal":
            if node.get("effect") not in (None, 0, 0.0):
                backup["terminals"][node_id] = node.get("effect")
            node["effect"] = 0.0
            continue
        for index, branch in enumerate(node.get("branches", []) or []):
            if branch.get("effect_increment") not in (None, 0, 0.0):
                backup["branches"][f"{node_id}::{index}"] = branch.get("effect_increment")
            if "effect_increment" in branch:
                branch["effect_increment"] = 0.0
    document["effect_backup"] = backup
    document["effect_disabled"] = True


def _tree_restore_effect(document: dict[str, Any]) -> None:
    backup = document.pop("effect_backup", None) or {}
    for node in document.get("nodes", []):
        node_id = node.get("id")
        if node.get("type") == "terminal":
            if node_id in backup.get("terminals", {}):
                node["effect"] = backup["terminals"][node_id]
            continue
        for index, branch in enumerate(node.get("branches", []) or []):
            key = f"{node_id}::{index}"
            if key in backup.get("branches", {}):
                branch["effect_increment"] = backup["branches"][key]
    document["effect_disabled"] = False


def render_outcomes_table(
    T: dict[str, str], document: dict[str, Any], key_prefix: str, allow_remove_effect: bool = False,
) -> None:
    """Render the Outcomes table (Model properties): a dropdown outcome
    type (Cost/Effect/ICER/NMB/CER/NHB), a customizable display symbol and
    decimal places per row, with native +/- row add/remove via
    st.data_editor's dynamic rows (see the docstring on
    ensure_document_outcomes for the id/primary-pair rules this enforces
    after every edit).

    ``allow_remove_effect`` (Tree Editor only, default False so every other
    editor keeps its "primary pair can never be removed" behaviour): lets
    the user delete the primary Effect row for a cost-only model. The
    Effect values already entered are backed up and zeroed
    (_tree_disable_effect) so canvas, Run, Analysis and SA/PSA all agree
    there is no effect, and restored if an Effect row is added back."""

    outcomes = ensure_document_outcomes(document)
    st.markdown(f"**{T['outcomes_table_title']}**")
    st.caption(T["outcomes_table_hint"])

    type_labels = {
        "cost": T["outcome_type_cost"],
        "effect": T["outcome_type_effect"],
        "icer": T["outcome_type_icer"],
        "nmb": T["outcome_type_nmb"],
        "cer": T["outcome_type_cer"],
        "nhb": T["outcome_type_nhb"],
    }
    source_rows = [
        {
            "id": row.get("id"),
            "type": row.get("type"),
            "label": row.get("label", ""),
            "symbol": row.get("symbol", ""),
            "decimals": int(row.get("decimals", 2) or 0),
        }
        for row in outcomes
    ]
    source_df = pd.DataFrame(source_rows, columns=["id", "type", "label", "symbol", "decimals"])
    edited_df = st.data_editor(
        source_df,
        hide_index=True,
        use_container_width=True,
        num_rows="dynamic",
        key=f"{key_prefix}_outcomes_editor",
        column_order=["type", "label", "symbol", "decimals"],
        column_config={
            "id": st.column_config.TextColumn(disabled=True),
            "type": st.column_config.SelectboxColumn(
                T["outcome_type_column"], options=OUTCOME_TYPES, required=True, default="cost",
                format_func=lambda value: type_labels.get(value, value),
            ),
            "label": st.column_config.TextColumn(T["outcome_label_column"]),
            # Not required: a required cell left empty keeps a new "+" row
            # client-side (never sent to Python), so the new outcome would
            # never reach the canvas / Edit panels. Empty symbol/decimals
            # get the type's defaults below instead.
            "symbol": st.column_config.TextColumn(T["outcome_symbol_column"]),
            "decimals": st.column_config.NumberColumn(
                T["decimal_place"], min_value=0, max_value=10, step=1, default=2
            ),
        },
    )

    edited_records = edited_df.to_dict("records")
    existing_ids = {
        str(row["id"]) for row in edited_records
        if row.get("id") not in (None, "") and not (isinstance(row.get("id"), float) and pd.isna(row.get("id")))
    }
    new_rows: list[dict[str, Any]] = []
    for row in edited_records:
        outcome_type = row.get("type") or "cost"
        if outcome_type not in OUTCOME_TYPES:
            outcome_type = "cost"
        row_id = row.get("id")
        is_empty_id = row_id in (None, "") or (isinstance(row_id, float) and pd.isna(row_id))
        # A non-primary row's id encodes the TYPE it had when the id was
        # assigned (e.g. "effect_2", "cost_3"). If the user later flips
        # that row's Type dropdown (say Cost -> Effect) without ever
        # clearing/re-adding the row, the id was never being re-derived --
        # it kept its old type prefix, so every downstream lookup that
        # trusts the id (canvas, Edit-state panel, engine outcome_kinds)
        # kept treating the row as its ORIGINAL type. That's the "pick
        # Effect, it behaves like Cost again" bug: the dropdown cell
        # itself did switch, but nothing else did. The 2 primary rows
        # ("cost"/"effect") are exempt -- their id is fixed by convention
        # elsewhere (the primary-pair re-insertion below, allow_remove_effect).
        id_type_mismatch = (
            not is_empty_id
            and row_id not in ("cost", "effect")
            and isinstance(row_id, str)
            and row_id.split("_", 1)[0] != outcome_type
        )
        if is_empty_id or id_type_mismatch:
            if outcome_type in ("cost", "effect") and outcome_type not in existing_ids:
                row_id = outcome_type
            elif outcome_type not in existing_ids:
                row_id = outcome_type
            else:
                row_id = _next_outcome_id(existing_ids, outcome_type)
            existing_ids.add(row_id)
        label = str(row.get("label") or "").strip() or type_labels.get(outcome_type, outcome_type.title())
        symbol = str(row.get("symbol") or "").strip()
        if not symbol or symbol.lower() == "none":
            # A new "+" row whose symbol isn't typed yet: give it a unique
            # default (E2, E3 ... / $2 ...) so it doesn't clash with the
            # primary pair and is saved -- and drawn on the canvas / Edit
            # panels -- straight away; the user then renames it (e.g. QALY).
            base_symbol = _default_outcome_symbol(outcome_type)
            used_symbols = {str(r.get("symbol") or "").strip().lower() for r in edited_records if r is not row}
            used_symbols |= {r["symbol"].strip().lower() for r in new_rows}
            symbol, suffix = base_symbol, 2
            while symbol.lower() in used_symbols:
                symbol, suffix = f"{base_symbol}{suffix}", suffix + 1
        decimals_raw = row.get("decimals")
        try:
            decimals = (
                int(decimals_raw)
                if decimals_raw is not None and not (isinstance(decimals_raw, float) and pd.isna(decimals_raw))
                else _default_outcome_decimals(outcome_type)
            )
        except (TypeError, ValueError):
            decimals = _default_outcome_decimals(outcome_type)
        new_rows.append({"id": row_id, "type": outcome_type, "label": label, "symbol": symbol, "decimals": decimals})

    # The primary Cost/Effect pair can never be removed -- re-insert a
    # default row if the user deleted it via the data_editor's row-delete.
    if not any(row["id"] == "cost" for row in new_rows):
        new_rows.insert(0, {
            "id": "cost", "type": "cost", "label": "Cost",
            "symbol": document.get("cost_symbol") or "$", "decimals": int(document.get("cost_decimals", 2)),
        })
    if not allow_remove_effect and not any(row["id"] == "effect" for row in new_rows):
        effect_index = next((i + 1 for i, row in enumerate(new_rows) if row["id"] == "cost"), len(new_rows))
        new_rows.insert(effect_index, {
            "id": "effect", "type": "effect", "label": "Effect",
            "symbol": document.get("effect_symbol") or "E", "decimals": int(document.get("effect_decimals", 4)),
        })

    if allow_remove_effect and not any(row["id"] == "effect" for row in new_rows):
        # A "+" row starts as type Cost (id like "cost_2"); when the user
        # switches it to Effect, promote it to the primary Effect row so the
        # model leaves cost-only mode and the canvas gets its Effect back.
        promoted = next((row for row in new_rows if row["type"] == "effect"), None)
        if promoted is not None:
            old_id = promoted["id"]
            promoted["id"] = "effect"
            for node in document.get("nodes", []):
                for holder in [node, *(node.get("branches", []) or [])]:
                    extras = holder.get("extra_outcomes")
                    if isinstance(extras, dict):
                        extras.pop(old_id, None)

    symbols_seen: dict[str, str] = {}
    duplicate = False
    for row in new_rows:
        key = row["symbol"].strip().lower()
        if not key:
            continue
        if key in symbols_seen and symbols_seen[key] != row["id"]:
            duplicate = True
            break
        symbols_seen[key] = row["id"]

    if duplicate:
        st.error(T["outcome_duplicate_symbol_error"])
    else:
        document["outcomes"] = new_rows
        if allow_remove_effect:
            effect_present = any(row["id"] == "effect" and row["type"] == "effect" for row in new_rows)
            if not effect_present and not document.get("effect_disabled"):
                _tree_disable_effect(document)
            elif effect_present and document.get("effect_disabled"):
                _tree_restore_effect(document)
        primary_cost = next((row for row in new_rows if row["id"] == "cost"), None)
        primary_effect = next((row for row in new_rows if row["id"] == "effect"), None)
        if primary_cost:
            document["cost_symbol"] = primary_cost["symbol"]
            document["cost_decimals"] = primary_cost["decimals"]
        if primary_effect:
            document["effect_symbol"] = primary_effect["symbol"]
            document["effect_decimals"] = primary_effect["decimals"]

        if st.button(
            T.get("outcomes_save_button", "Save"),
            icon=":material/save:",
            key=f"{key_prefix}_outcomes_save",
        ):
            st.toast(T.get("outcomes_save_confirm", "Saved -- the canvas is synced with your Outcomes table."), icon="✅")
            st.rerun()


def _tree_discount_rates(document: dict[str, Any]) -> tuple[float, float]:
    """Annual cost/effect discount rates for the Decision Tree, straight
    from the Discount table in Model properties -- there is no cycle
    concept here (unlike Markov), so the rate is always a plain per-year
    rate applied to each terminal node's ``year`` field. Both default to
    0.0, matching how every model behaved before discounting existed."""

    cost_rate = float(document.get("discount_cost_value", 0.0))
    effect_rate = float(document.get("discount_effect_value", 0.0))
    return cost_rate, effect_rate


def _tree_extra_outcome_kinds(document: dict[str, Any]) -> dict[str, str]:
    """{outcome_id: "cost"|"effect"} for every Cost/Effect outcome BEYOND
    the primary pair (id not "cost"/"effect") -- what Engine.run()'s
    outcome_kinds parameter needs in order to also compute and discount
    them. Empty for a model with no extra outcomes added in the Outcomes
    table."""

    return {
        row["id"]: row["type"]
        for row in ensure_document_outcomes(document)
        if row["type"] in ("cost", "effect") and row["id"] not in ("cost", "effect")
    }


@st.cache_data(show_spinner=False)
def _tree_preview_totals_cached(document_json: str, allow_negative: bool) -> dict[str, Any] | None:
    """Cheap, read-only per-strategy cost/effect totals for the tree's
    Analysis live preview, cached on the document's own JSON like the
    Markov equivalent. Returns None the moment any branch is missing
    cost/effect increments, or the tree fails to resolve/run cleanly.
    "extra" carries the total for every non-primary Cost/Effect outcome
    from the Outcomes table, keyed by outcome id."""

    document = json.loads(document_json)
    for node in document.get("nodes", []):
        if node.get("type") == "decision":
            continue  # strategy branches take no cost/effect input
        for branch in node.get("branches", []):
            if "cost_increment" not in branch or (
                "effect_increment" not in branch and not document.get("effect_disabled")
            ):
                return None
    try:
        tree, parameters = resolve(document)
    except Exception:  # noqa: BLE001
        return None
    cost_rate, effect_rate = _tree_discount_rates(document)
    outcome_kinds = _tree_extra_outcome_kinds(document)
    tree_distributions = {
        str(raw["name"]): raw for raw in document.get("distributions", []) if raw.get("name")
    }
    tree_tables = build_tables_mapping(document.get("tables"))
    try:
        result = Engine().run(
            tree, parameters, allow_negative_cost=allow_negative,
            cost_discount_rate=cost_rate, effect_discount_rate=effect_rate,
            outcome_kinds=outcome_kinds,
            distributions=tree_distributions, tables=tree_tables,
        )
    except Exception:  # noqa: BLE001 - an expression that does not parse (typo, text) must not crash the page; show nothing yet
        return None
    if result.errors or not result.strategies:
        return None
    return {
        label: {
            "name": label, "cost": strategy.cost, "effect": strategy.effect,
            "extra": dict(strategy.extra_totals),
        }
        for label, strategy in result.strategies.items()
    }


def _tree_preview_totals(document: dict[str, Any], allow_negative: bool) -> dict[str, Any] | None:
    try:
        document_json = json.dumps(document, sort_keys=True, default=str)
    except TypeError:
        return None
    return _tree_preview_totals_cached(document_json, allow_negative)


def _tree_analysis_outcome_selection(
    T: dict[str, str], document: dict[str, Any], analysis: dict[str, Any]
) -> tuple[str, str, str, int, str, int]:
    """Render the Cost-outcome / Effect-outcome picker (only shown when
    the Outcomes table has more than one Cost or more than one Effect row)
    and return (cost_id, effect_id, cost_symbol, cost_decimals,
    effect_symbol, effect_decimals) for whichever pair is selected to
    feed ICER/NMB -- defaulting to the primary "cost"/"effect" pair, per
    the user's answer that this is a user choice, not automatic."""

    outcomes = ensure_document_outcomes(document)
    cost_rows = [row for row in outcomes if row["type"] == "cost"]
    effect_rows = [row for row in outcomes if row["type"] == "effect"]

    if len(cost_rows) > 1 or len(effect_rows) > 1:
        picker_cost_col, picker_effect_col = st.columns(2)
        with picker_cost_col:
            cost_options = [row["id"] for row in cost_rows]
            cost_option_labels = {row["id"]: (row.get("label") or row["id"]) for row in cost_rows}
            current_cost_id = analysis.get("cost_outcome_id") or "cost"
            if current_cost_id not in cost_options:
                current_cost_id = cost_options[0] if cost_options else "cost"
            analysis["cost_outcome_id"] = st.selectbox(
                T["outcome_cost_picker"], cost_options, index=cost_options.index(current_cost_id),
                format_func=lambda oid: cost_option_labels.get(oid, oid), key="tree_analysis_cost_outcome_input",
            )
        with picker_effect_col:
            effect_options = [row["id"] for row in effect_rows]
            effect_option_labels = {row["id"]: (row.get("label") or row["id"]) for row in effect_rows}
            current_effect_id = analysis.get("effect_outcome_id") or "effect"
            if not effect_options:
                # Cost-only model (Effect row deleted): nothing to pick.
                analysis["effect_outcome_id"] = "effect"
            else:
                if current_effect_id not in effect_options:
                    current_effect_id = effect_options[0]
                analysis["effect_outcome_id"] = st.selectbox(
                    T["outcome_effect_picker"], effect_options, index=effect_options.index(current_effect_id),
                    format_func=lambda oid: effect_option_labels.get(oid, oid), key="tree_analysis_effect_outcome_input",
                )
    else:
        analysis["cost_outcome_id"] = "cost"
        analysis["effect_outcome_id"] = "effect"

    cost_id = analysis["cost_outcome_id"]
    effect_id = analysis["effect_outcome_id"]
    cost_row = next((row for row in cost_rows if row["id"] == cost_id), cost_rows[0] if cost_rows else None)
    effect_row = next((row for row in effect_rows if row["id"] == effect_id), effect_rows[0] if effect_rows else None)
    cost_symbol = (cost_row or {}).get("symbol") or "$"
    cost_decimals = int((cost_row or {}).get("decimals", 2))
    effect_symbol = (effect_row or {}).get("symbol") or "E"
    effect_decimals = int((effect_row or {}).get("decimals", 4))
    return cost_id, effect_id, cost_symbol, cost_decimals, effect_symbol, effect_decimals


def _tree_outcome_value(values: dict[str, Any], outcome_id: str, primary_key: str) -> float:
    """Pull one strategy's total for the outcome selected to feed
    ICER/NMB -- the primary cost/effect field for "cost"/"effect", or
    from "extra" (see _tree_preview_totals_cached) for any other id."""

    if outcome_id == primary_key:
        return float(values.get(primary_key, 0.0) or 0.0)
    return float((values.get("extra") or {}).get(outcome_id, 0.0) or 0.0)


def _render_cma_cba_preview(
    T: dict[str, str],
    analysis: dict[str, Any],
    analysis_type: str,
    names: dict[str, str],
    cost_values: dict[str, float],
    effect_values: dict[str, float],
    cost_symbol: str,
    cost_decimals: int,
    effect_symbol: str,
    effect_decimals: int,
    baseline_id: str | None,
    key_prefix: str,
) -> None:
    """Live preview for Cost-Minimization (CMA) and Cost-Benefit (CBA)
    analysis, shared by every model type's Analysis section (tree, Markov,
    PSM, microsim, DES). The maths lives in heor_tree_engine.cma_cba."""

    ids = list(names)
    labels = [names[sid] for sid in ids]
    costs = [float(cost_values[sid]) for sid in ids]
    effects = [float(effect_values[sid]) for sid in ids]
    cost_col = f"{T['total_cost']} ({cost_symbol})"
    effect_col = f"{T['total_effect']} ({effect_symbol})"

    if analysis_type == "CMA":
        tol_pct = st.number_input(
            T["cma_tolerance"], min_value=0.0, max_value=100.0,
            value=float(analysis.get("cma_tolerance_pct", 1.0)), step=0.5,
            key=f"{key_prefix}_cma_tolerance_input",
        )
        analysis["cma_tolerance_pct"] = tol_pct
        result = _cma_cba.cma_analysis(labels, costs, effects, tolerance=tol_pct / 100.0)
        rows = [
            {
                T["strategy_name"]: row.name,
                cost_col: f"{row.cost:,.{cost_decimals}f}",
                effect_col: f"{row.effect:,.{effect_decimals}f}",
                T["cma_extra_cost"]: f"{row.extra_cost_vs_cheapest:,.{cost_decimals}f}",
                " ": T["cma_cheapest_flag"] if row.is_cheapest else "",
            }
            for row in result.rows
        ]
        _blue_header_table(pd.DataFrame(rows))
        if result.effects_equivalent:
            st.info(T["cma_ok"].format(tol=result.tolerance, spread=result.effect_spread))
        else:
            st.warning(T["cma_warning"].format(tol=result.tolerance, spread=result.effect_spread))
        if result.ties:
            st.caption(T["cma_tie"].format(names=", ".join(result.ties)))
        st.success(T["cma_cheapest"].format(name=result.cheapest))
        return

    # CBA
    value = st.number_input(
        T["cba_value_per_effect"], min_value=0.0,
        value=float(analysis.get("cba_value_per_effect", analysis.get("willingness_to_pay", 50000.0))),
        step=1000.0, key=f"{key_prefix}_cba_value_input",
    )
    analysis["cba_value_per_effect"] = value
    stored = analysis.setdefault("cba_extra_benefits", {})
    with st.expander(T["cba_extra_benefits"]):
        for label in labels:
            stored[label] = st.number_input(
                T["cba_extra_benefit_for"].format(name=label),
                value=float(stored.get(label, 0.0) or 0.0), step=1000.0,
                key=f"{key_prefix}_cba_extra_{label}",
            )
    st.caption(T["cba_discount_note"])
    maximize = analysis.get("effect_objective", "maximize") == "maximize"
    baseline_label = names.get(baseline_id) if baseline_id else None
    result = _cma_cba.cba_analysis(
        labels, costs, effects, value, maximize_effect=maximize,
        extra_benefits=stored, baseline=baseline_label,
    )
    st.caption(T["cba_baseline_info"].format(name=result.baseline))

    def money(x: float | None) -> str:
        return "-" if x is None else f"{x:,.{cost_decimals}f}"

    def ratio(x: float | None) -> str:
        return "-" if x is None else f"{x:,.2f}"

    note_text = {
        "": "", "baseline": T["cba_note_baseline"], "dominant": T["cba_note_dominant"],
        "dominated": T["cba_note_dominated"],
        "cheaper_less_benefit": T["cba_note_cheaper_less_benefit"],
        "no_cost_change": T["cba_note_no_cost_change"],
    }
    rows = [
        {
            T["strategy_name"]: row.name,
            cost_col: money(row.cost),
            effect_col: f"{row.effect:,.{effect_decimals}f}",
            f"{T['cba_benefit']} ({cost_symbol})": money(row.benefit),
            f"{T['cba_net_benefit']} ({cost_symbol})": money(row.net_benefit),
            T["cba_delta_cost"]: money(row.delta_cost),
            T["cba_delta_benefit"]: money(row.delta_benefit),
            T["cba_delta_net"]: money(row.delta_net_benefit),
            T["cba_bcr"]: ratio(row.bcr),
            T["cba_roi"]: "-" if row.roi is None else f"{row.roi:.1%}",
            " ": note_text.get(row.bcr_note, ""),
        }
        for row in result.rows
    ]
    _blue_header_table(pd.DataFrame(rows))
    chart_df = pd.DataFrame({
        T["strategy_name"]: [r.name for r in result.rows],
        f"{T['cba_net_benefit']} ({cost_symbol})": [r.net_benefit for r in result.rows],
    })
    net_col = f"{T['cba_net_benefit']} ({cost_symbol})"
    best_net = max(r.net_benefit for r in result.rows)
    bar = alt.Chart(chart_df).mark_bar().encode(
        x=alt.X(T["strategy_name"], type="nominal", sort="-y"),
        y=alt.Y(net_col, type="quantitative"),
        color=alt.condition(alt.datum[net_col] == best_net, alt.value("#16a34a"), alt.value("#94a3b8")),
        tooltip=list(chart_df.columns),
    )
    st.altair_chart(bar, use_container_width=True)
    st.success(T["cba_best"].format(name=result.best))


def _render_formula_check_expander() -> None:
    """Tree: list every formula problem in the model at once (unknown names / functions,
    syntax errors, duplicate names, circular variables), with 'Did you mean' hints."""

    from heor_tree_engine.formula_check import check_document_formulas

    with _setting_panel("tree_check", "Check formulas"):
        st.caption("Scans every formula in the model (probabilities, payoffs, parameters, variables) without running it.")
        if st.button("Check all formulas", key="formula_check_go"):
            st.session_state["formula_check_result"] = [
                issue.as_row() for issue in check_document_formulas(st.session_state.document)
            ]
        result = st.session_state.get("formula_check_result")
        if result is None:
            return
        if not result:
            st.success("No formula problems found.")
        else:
            st.error(f"{len(result)} problem(s) found.")
            st.dataframe(pd.DataFrame(result), use_container_width=True, hide_index=True)


def _render_bayes_revision_expander() -> None:
    """Tree: add a Bayes-revised screening/diagnostic test subtree.

    Takes prevalence, sensitivity and specificity and builds the Test result
    -> Disease status chance structure with the revised probabilities as
    derived variables (so SA / PSA / VOI recompute them for every draw).
    See bayes_revision.py."""

    from heor_tree_engine.bayes_revision import add_binary_bayes_structure

    with _setting_panel("tree_bayes", "Bayes revision (diagnostic test)"):
        st.caption(
            "Builds Test result -> Disease status from prevalence, sensitivity and "
            "specificity. Enter a number or the name of a parameter/expression."
        )
        nodes = [n for n in st.session_state.document["nodes"] if n.get("type") != "terminal"]
        node_ids = [n["id"] for n in nodes]
        selected = st.session_state.get("selected_id")
        default_index = node_ids.index(selected) if selected in node_ids else 0
        cols = st.columns([1.2, 1, 1, 1, 1])
        parent_id = cols[0].selectbox("Attach to node", node_ids, index=default_index, key="bayes_parent", format_func=_tree_node_option_label)
        prior = cols[1].text_input("Prevalence P(D)", value="", key="bayes_prior")
        sens = cols[2].text_input("Sensitivity", value="", key="bayes_se")
        spec = cols[3].text_input("Specificity", value="", key="bayes_sp")
        prefix = cols[4].text_input("Name prefix", value="test", key="bayes_prefix")
        label_cols = st.columns(2)
        test_label = label_cols[0].text_input("Test name", value="Test", key="bayes_test_label")
        disease_label = label_cols[1].text_input("Disease name", value="Disease", key="bayes_disease_label")
        if st.button("Add Bayes revision", key="bayes_add"):
            error, new_root = add_binary_bayes_structure(
                st.session_state.document, parent_id, prefix, prior, sens, spec,
                disease_label=disease_label.strip() or "Disease",
                test_label=test_label.strip() or "Test",
            )
            if error:
                st.error(error)
            else:
                auto_layout()
                st.session_state.selected_id = new_root
                st.session_state.flow_component_version += 1
                st.session_state.flow_fitted = False
                mark_flow_changed()
                st.session_state._setting_open = None
                st.rerun()

    _render_bayes_matrix_and_flip(nodes, node_ids, default_index)


def _render_bayes_matrix_and_flip(nodes: list[dict[str, Any]], node_ids: list[str], default_index: int) -> None:
    """Tree: n-state / m-result Bayes revision and Flip of two chance levels."""

    from heor_tree_engine.bayes_revision import add_matrix_bayes_structure, flip_chance_tree

    def finish(new_id: str) -> None:
        auto_layout()
        st.session_state.selected_id = new_id
        st.session_state.flow_component_version += 1
        st.session_state.flow_fitted = False
        mark_flow_changed()
        st.session_state._setting_open = None
        st.rerun()

    with _setting_panel("tree_bayes_matrix", "Bayes revision: several states / results (matrix)"):
        st.caption(
            "Comma-separated lists. Likelihood: one line per disease state, P(result | state) "
            "for each result; '#' = remainder of the row (or of the prior list)."
        )
        parent_id = st.selectbox("Attach to node", node_ids, index=default_index, key="bayes_m_parent", format_func=_tree_node_option_label)
        c1, c2 = st.columns(2)
        states_text = c1.text_input("Disease states", value="Healthy, Mild, Severe", key="bayes_m_states")
        priors_text = c2.text_input("Prior P(state)", value="0.7, 0.2, #", key="bayes_m_priors")
        results_text = c1.text_input("Test results", value="Negative, Equivocal, Positive", key="bayes_m_results")
        prefix = c2.text_input("Name prefix", value="bm", key="bayes_m_prefix")
        lik_text = st.text_area(
            "Likelihood rows", value="0.9, 0.08, #\n0.2, 0.3, 0.5\n0.05, #, 0.75", key="bayes_m_lik", height=90,
        )
        test_label = st.text_input("Test name", value="Test", key="bayes_m_test_label")
        if st.button("Add matrix Bayes revision", key="bayes_m_add"):
            split = lambda text: [x.strip() for x in text.split(",") if x.strip()]
            rows = [split(line) for line in lik_text.splitlines() if line.strip()]
            error, new_root = add_matrix_bayes_structure(
                st.session_state.document, parent_id, prefix, split(states_text), split(priors_text),
                split(results_text), rows, test_label=test_label.strip() or "Test",
            )
            if error:
                st.error(error)
            else:
                finish(new_root)

    with _setting_panel("tree_flip", "Flip tree (Disease → Test becomes Test → Disease)"):
        st.caption(
            "Select a chance node whose children are chance nodes with the same branch labels "
            "(e.g. Disease, then Test result). The order of the two levels is swapped with Bayes' rule; "
            "the subtrees below are kept. Move any payoffs on those branches to the terminals first."
        )
        chance_ids = [n["id"] for n in nodes if n.get("type") == "chance"]
        if not chance_ids:
            st.caption("No chance nodes.")
            return
        selected = st.session_state.get("selected_id")
        flip_id = st.selectbox("Node to flip", chance_ids, index=chance_ids.index(selected) if selected in chance_ids else 0, key="bayes_flip_node", format_func=_tree_node_option_label)
        flip_prefix = st.text_input("Name prefix for the new probabilities", value="flip", key="bayes_flip_prefix")
        if st.button("Flip", key="bayes_flip_go"):
            error, new_id = flip_chance_tree(st.session_state.document, flip_id, flip_prefix)
            if error:
                st.error(error)
            else:
                finish(new_id)


def _render_tree_markov_node_panel() -> None:
    """Tree: edit the selected Markov node (states, transitions, cycles).

    A Markov node is a whole cohort model rolled back as one node of the
    tree (see MarkovTreeNode). Costs, effects and probabilities may be
    numbers or any parameter/variable expression of the tree, including
    _cycle and _tenure."""

    import pandas as pd

    from heor_tree_engine.tree_markov_node import (
        STATE_COLUMNS, TRANSITION_COLUMNS, import_markov_strategy, rows_to_states, rows_to_transitions,
        states_to_rows, strategies_of, table_problems, transitions_to_rows,
    )

    document = st.session_state.document
    node = next((n for n in document["nodes"] if n["id"] == st.session_state.get("selected_id")), None)
    if node is None or node.get("type") != "markov":
        return
    with st.expander(f"Markov node: {node['id']}", expanded=True):
        st.caption(
            "A cohort Markov model run for this branch of the tree. Cost/effect/probability can be numbers or "
            "expressions (parameters, variables, _cycle, _tenure). Use # for the remaining probability."
        )
        rev = st.session_state.get(f"mkt_rev_{node['id']}", 0)
        with st.expander("Import from a Markov model file", expanded=False):
            st.caption(
                "Copies one strategy (states, transitions, cycles) from a saved Markov model (.decide). It is a copy: "
                "later edits to the Markov file do not reach this node. Parameters, variables, distributions and "
                "tables the tree does not have yet can be copied too (existing names keep the tree's value)."
            )
            upload = st.file_uploader("Markov model file", type=["decide", "json"], key=f"mkt_upload_{node['id']}")
            if upload is not None:
                markov_doc, parse_error = _model_files_parse(upload.getvalue().decode("utf-8", errors="replace"), "strategies")
                if parse_error or not strategies_of(markov_doc):
                    st.error(parse_error or "This Markov file has no strategies.")
                else:
                    options = strategies_of(markov_doc)
                    chosen = st.selectbox(
                        "Strategy", [sid for sid, _ in options],
                        format_func=lambda sid: dict(options)[sid], key=f"mkt_import_strategy_{node['id']}",
                    )
                    merge = st.checkbox("Also copy missing parameters, variables, distributions and tables",
                                        value=True, key=f"mkt_import_merge_{node['id']}")
                    if st.button("Import into this node", key=f"mkt_import_btn_{node['id']}"):
                        error, report = import_markov_strategy(node, document, markov_doc, chosen, merge)
                        if error:
                            st.error(error)
                        else:
                            st.session_state[f"mkt_rev_{node['id']}"] = rev + 1
                            st.session_state["mkt_import_report"] = report
                            st.rerun()
        report = st.session_state.pop("mkt_import_report", None)
        if report:
            st.success("Imported.")
            if report.get("added"):
                st.caption("Added to this tree: " + ", ".join(report["added"]))
            if report.get("conflicts"):
                st.warning("Already in this tree with a different value (tree's value kept): " + ", ".join(report["conflicts"]))
        cols = st.columns(3)
        node["cycles"] = int(cols[0].number_input(
            "Cycles", min_value=1, value=int(node.get("cycles", 10)), step=1, key=f"mkt_cycles_{node['id']}_{rev}"))
        node["cycles_per_year"] = float(cols[1].number_input(
            "Cycles per year", min_value=0.01, value=float(node.get("cycles_per_year", 1.0)),
            key=f"mkt_cpy_{node['id']}_{rev}",
            help="Used to turn the tree's annual discount rates into per-cycle rates."))
        node["half_cycle_correction"] = cols[2].checkbox(
            "Half-cycle correction", value=bool(node.get("half_cycle_correction", True)),
            key=f"mkt_half_{node['id']}_{rev}")
        st.markdown("**States**")
        state_df = st.data_editor(
            pd.DataFrame(states_to_rows(node.get("states", [])), columns=list(STATE_COLUMNS)),
            num_rows="dynamic", use_container_width=True, hide_index=True, key=f"mkt_states_{node['id']}_{rev}",
            column_config={
                "is_absorbing": st.column_config.CheckboxColumn("is_absorbing", default=False),
                "id": st.column_config.TextColumn("id", required=True),
            },
        )
        st.markdown("**Transitions**")
        trans_df = st.data_editor(
            pd.DataFrame(transitions_to_rows(node.get("transitions", [])), columns=list(TRANSITION_COLUMNS)),
            num_rows="dynamic", use_container_width=True, hide_index=True, key=f"mkt_trans_{node['id']}_{rev}",
        )
        new_states = rows_to_states(state_df.to_dict("records"), node.get("states", []))
        new_transitions = rows_to_transitions(trans_df.to_dict("records"), node.get("transitions", []))
        node["states"], node["transitions"] = new_states, new_transitions
        for problem in table_problems(new_states, new_transitions):
            st.warning(problem)


def _render_tree_trackers_panel() -> None:
    """Tree: tracker variables (values that travel with one simulated individual), their updates on the
    selected node, and the Group Monte Carlo run. See tree_montecarlo.py."""

    import numpy as np

    from heor_tree_engine.tree_montecarlo import run_group_mc_document, tracker_problems

    document = st.session_state.document
    with _setting_panel("tree_trackers", "Trackers & Group Monte Carlo"):
        st.caption(
            "A tracker is a value carried by each simulated individual (e.g. age, number of events). "
            "It starts at its initial value, changes at nodes ('Tracker updates') and can be used in "
            "probabilities and payoffs of the nodes below. Group Monte Carlo simulates individuals one by one; "
            "the normal Run ignores trackers."
        )
        st.markdown("**Trackers**")
        trackers = document.get("trackers") or []
        frame = pd.DataFrame(
            [{"name": str(t.get("name", "")), "initial": str(t.get("initial", 0))} for t in trackers],
            columns=["name", "initial"],
        )
        edited = st.data_editor(
            frame, num_rows="dynamic", hide_index=True, use_container_width=True, key="tree_trackers_editor",
            column_config={"name": st.column_config.TextColumn("Name"),
                           "initial": st.column_config.TextColumn("Initial value (number or expression)")},
        )
        def cell(value: Any) -> str:
            return "" if value is None or (isinstance(value, float) and value != value) else str(value).strip()

        new_trackers = []
        for _, row in edited.iterrows():
            name = cell(row.get("name"))
            if name:
                text = cell(row.get("initial")) or "0"
                try:
                    initial: Any = float(text)
                except ValueError:
                    initial = text
                new_trackers.append({"name": name, "initial": initial})
        if new_trackers:
            document["trackers"] = new_trackers
        else:
            document.pop("trackers", None)

        node = next((n for n in document.get("nodes", []) if n.get("id") == st.session_state.get("selected_id")), None)
        if node is not None and document.get("trackers"):
            st.markdown(f"**Tracker updates on node '{node['id']}'** (run in order when an individual enters it)")
            names = [t["name"] for t in document["trackers"]]
            current = node.get("tracker_updates") or []
            upd_frame = pd.DataFrame(
                [{"tracker": str(u.get("tracker", "")), "expr": str(u.get("expr", ""))} for u in current],
                columns=["tracker", "expr"],
            )
            upd_edited = st.data_editor(
                upd_frame, num_rows="dynamic", hide_index=True, use_container_width=True,
                key=f"tree_tracker_updates_{node['id']}",
                column_config={"tracker": st.column_config.SelectboxColumn("Tracker", options=names),
                               "expr": st.column_config.TextColumn("New value, e.g. nEvents + 1")},
            )
            rows = [{"tracker": cell(r.get("tracker")), "expr": cell(r.get("expr"))}
                    for _, r in upd_edited.iterrows() if cell(r.get("tracker"))]
            if rows:
                node["tracker_updates"] = rows
            else:
                node.pop("tracker_updates", None)
        elif node is not None:
            st.caption("Add a tracker above to set updates on the selected node.")
        with_updates = [n["id"] for n in document.get("nodes", []) if n.get("tracker_updates")]
        if with_updates:
            st.caption("Nodes with tracker updates: " + ", ".join(with_updates))

        st.markdown("**Group Monte Carlo**")
        st.markdown(
            "<style>.st-key-tree_gmc_run button{background:#dc2626;border-color:#dc2626;color:#fff;}"
            ".st-key-tree_gmc_run button:hover{background:#b91c1c;border-color:#b91c1c;color:#fff;}"
            ".st-key-tree_gmc_run button p{color:#fff;}</style>",
            unsafe_allow_html=True,
        )
        c1, c2, c3 = st.columns([1, 1, 1])
        n_people = int(c1.number_input("Individuals per strategy", min_value=10, max_value=2_000_000, value=int(st.session_state.get("tree_gmc_n", 5000)), step=1000, key="tree_gmc_n"))
        seed = int(c2.number_input("Seed", min_value=0, value=int(st.session_state.get("tree_gmc_seed", 2026)), step=1, key="tree_gmc_seed"))
        if c3.button("Run group Monte Carlo", icon=":material/play_arrow:", key="tree_gmc_run", use_container_width=True):
            problems = tracker_problems(document)
            if problems:
                st.error("\n".join(problems))
            else:
                try:
                    with st.spinner("Simulating individuals..."):
                        st.session_state["tree_gmc_result"] = run_group_mc_document(
                            document, n=n_people, seed=seed, outcome_kinds=_tree_extra_outcome_kinds(document),
                        )
                except Exception as exc:  # noqa: BLE001 -- show the model problem instead of crashing the editor
                    st.session_state.pop("tree_gmc_result", None)
                    st.error(f"Group Monte Carlo failed: {exc}")
        result = st.session_state.get("tree_gmc_result")
        if result is None:
            return
        for message in result.warnings:
            st.warning(message)
        summary = result.summary()
        rows = []
        for entry in summary:
            row = {"Strategy": entry["strategy"]}
            for oid in result.outcome_ids:
                o = entry[oid]
                row[oid.capitalize()] = f"{o['mean']:,.2f} ({o['lower']:,.2f} to {o['upper']:,.2f})"
            rows.append(row)
        st.caption(f"{result.n:,} individuals per strategy, seed {result.seed}; mean (95% CI).")
        st.dataframe(pd.DataFrame(rows), use_container_width=True, hide_index=True)
        strategies = result.strategies
        if len(strategies) > 1:
            baseline = st.selectbox("Baseline strategy", strategies, key="tree_gmc_baseline")
            inc_rows = []
            for name in strategies:
                if name == baseline:
                    continue
                inc = result.incremental(name, baseline)
                inc_rows.append({
                    "Strategy": name, "Incremental cost": f"{inc['cost']['mean']:,.2f} (SE {inc['cost']['se']:,.2f})",
                    "Incremental effect": f"{inc['effect']['mean']:,.4f} (SE {inc['effect']['se']:,.4f})",
                    "ICER": "-" if inc["icer"] is None else f"{inc['icer']:,.2f}",
                })
            st.dataframe(pd.DataFrame(inc_rows), use_container_width=True, hide_index=True)
        tracker_means = [{"Strategy": s_, **{t: f"{v.mean():,.3f}" for t, v in result.tracker_final[s_].items()}}
                         for s_ in strategies if result.tracker_final[s_]]
        if tracker_means:
            st.markdown("**Mean final tracker values**")
            st.dataframe(pd.DataFrame(tracker_means), use_container_width=True, hide_index=True)
        outcome = st.selectbox("Distribution of", result.outcome_ids, key="tree_gmc_hist_outcome")
        all_values = np.concatenate([result.outcomes[s_][outcome] for s_ in strategies])
        edges = np.histogram_bin_edges(all_values, bins=30)
        centers = np.round((edges[:-1] + edges[1:]) / 2.0, 4)
        hist = pd.DataFrame({s_: np.histogram(result.outcomes[s_][outcome], bins=edges)[0] for s_ in strategies}, index=centers)
        st.bar_chart(hist)


def _render_tree_clone_expander() -> None:
    """Tree: reusable subtree (TreeAge-style clone of a decision/chance node).

    A clone is a node that always mirrors another node's branches and
    descendants (the master); name substitutions swap parameter names inside
    the copy. See tree_clone.py."""

    from heor_tree_engine.tree_clone import add_tree_clone, make_independent_copy, parse_substitutions, tree_clone_errors

    document = st.session_state.document
    with _setting_panel("tree_clone", "Reuse subtree (clone)"):
        st.caption(
            "A clone mirrors another node's whole subtree. Edit the master and every clone updates. "
            "Substitutions rename parameters inside the copy, one per line: old -> new."
        )
        nodes = [n for n in document["nodes"] if n.get("type") in ("decision", "chance")]
        parents = [n["id"] for n in nodes]
        masters = [n["id"] for n in nodes if not n.get("clone_of")]
        if not masters:
            st.info("Add a decision or chance node first.")
            return
        selected = st.session_state.get("selected_id")
        cols = st.columns([1.2, 1.2, 1])
        parent_id = cols[0].selectbox(
            "Attach clone under", parents, index=parents.index(selected) if selected in parents else 0,
            key="clone_parent", format_func=_tree_node_option_label,
        )
        master_id = cols[1].selectbox("Master (copy this)", masters, key="clone_master", format_func=_tree_node_option_label)
        clone_name = cols[2].text_input("Clone name", value="", key="clone_name")
        subs_text = st.text_area("Substitutions", value="", key="clone_subs", height=80,
                                 placeholder="p_event_a -> p_event_b\nc_drug_a -> c_drug_b")
        if st.button("Add clone", key="clone_add"):
            error = add_tree_clone(document, parent_id, master_id, clone_name, parse_substitutions(subs_text))
            if error:
                st.error(error)
            else:
                auto_layout()
                st.session_state.selected_id = clone_name.strip()
                st.session_state.flow_component_version += 1
                st.session_state.flow_fitted = False
                mark_flow_changed()
                st.session_state._setting_open = None
                st.rerun()

        clones = [n["id"] for n in document["nodes"] if n.get("clone_of") and n.get("type") in ("decision", "chance")]
        if clones:
            st.markdown("**Existing clones**")
            for clone_id in clones:
                node = next(n for n in document["nodes"] if n["id"] == clone_id)
                row = st.columns([3, 1.2])
                row[0].write(f"{_tree_node_option_label(clone_id)} mirrors {_tree_node_option_label(node['clone_of'])}"
                             + (f" ({', '.join(f'{k}->{v}' for k, v in (node.get('clone_substitutions') or {}).items())})"
                                if node.get("clone_substitutions") else ""))
                if row[1].button("Make independent copy", key=f"clone_detach_{clone_id}"):
                    error = make_independent_copy(document, clone_id)
                    if error:
                        st.error(error)
                    else:
                        auto_layout()
                        st.session_state.flow_component_version += 1
                        st.session_state.flow_fitted = False
                        mark_flow_changed()
                        st.session_state._setting_open = None
                        st.rerun()
            for clone_id, message in tree_clone_errors(document):
                st.error(f"{_tree_node_option_label(clone_id)}: {message}")


def _render_tree_risk_preference(document: dict[str, Any], analysis: dict[str, Any]) -> None:
    """Risk preference (utility) for the Decision Tree: rank strategies by expected
    utility of path NMB instead of expected value (TreeAge's Risk Preference Function)."""

    from heor_tree_engine.risk_preference import UTILITY_KINDS, analyze_paths, results_to_records

    with st.expander("Risk preference (expected utility)"):
        st.caption(
            "Ranks strategies by expected utility of each path's net monetary benefit "
            "(WTP x effect - cost) instead of its expected value. R is the risk tolerance, "
            "in the same money unit: smaller R = more risk-averse."
        )
        labels = {"exponential": "Risk-averse (exponential)", "risk_seeking": "Risk-seeking", "neutral": "Risk-neutral"}
        saved = analysis.get("risk_preference") or {}
        kinds = list(UTILITY_KINDS)
        kind = st.selectbox(
            "Utility function", kinds,
            index=kinds.index(saved["kind"]) if saved.get("kind") in kinds else 0,
            format_func=lambda k: labels[k], key="tree_risk_kind",
        )
        wtp_default = float(analysis.get("willingness_to_pay", 50000.0) or 50000.0)
        wtp = st.number_input("Willingness to pay per unit of effect", min_value=0.0, value=wtp_default, step=1000.0, key="tree_risk_wtp")
        tolerance = st.number_input(
            "Risk tolerance R", min_value=1.0, value=float(saved.get("risk_tolerance", 100000.0)), step=10000.0,
            key="tree_risk_R", disabled=(kind == "neutral"),
        )
        analysis["risk_preference"] = {"kind": kind, "risk_tolerance": float(tolerance)}
        try:
            tree, parameters = resolve(document)
            cost_rate, effect_rate = _tree_discount_rates(document)
            distributions = {str(raw["name"]): raw for raw in document.get("distributions", []) if raw.get("name")}
            tables = build_tables_mapping(document.get("tables"))
            rows = tree_enumerate_paths(tree, parameters, None, distributions, cost_rate, effect_rate, {}, tables)
            results = analyze_paths(rows, wtp, kind, float(tolerance))
        except Exception as exc:  # noqa: BLE001 -- a settings panel must never crash the page
            st.caption(f"Risk preference unavailable: {exc}")
            return
        frame = pd.DataFrame(results_to_records(results))
        st.dataframe(frame.style.format({c: "{:,.2f}" for c in frame.columns if c not in ("Rank", "Strategy")}), use_container_width=True, hide_index=True)
        best = min(results, key=lambda r: r.rank)
        st.success(f"Best by expected utility: {best.strategy}")


def _render_tree_analysis_section(T: dict[str, str], document: dict[str, Any], allow_negative: bool) -> None:
    """Amua-inspired 'Analysis' settings for the Decision Tree's Model
    properties panel -- the same Analysis type (EV/CEA/BCA), Effect
    objective, Baseline strategy and WTP as the Markov model, with a live
    preview, but driven by the tree's own Engine instead of run_markov().
    When the Outcomes table has more than one Cost or Effect outcome, an
    extra picker lets the user choose which pair feeds ICER/NMB (see
    _tree_analysis_outcome_selection)."""

    analysis = _markov_ensure_analysis_settings(document)

    type_options = ["EV", "CEA", "CMA", "CBA"]
    type_labels = {
        "EV": T["analysis_type_ev"],
        "CEA": T["analysis_type_cea"],
        "CMA": T["analysis_type_cma"],
        "CBA": T["analysis_type_cba"],
    }
    type_help = {
        "EV": T["analysis_type_ev_help"],
        "CEA": T["analysis_type_cea_help"],
        "CMA": T["analysis_type_cma_help"],
        "CBA": T["analysis_type_cba_help"],
    }
    current_type = analysis.get("type", "CEA")
    if current_type not in type_options:
        current_type = "CEA"
    analysis["type"] = st.selectbox(
        T["analysis_type"], type_options, index=type_options.index(current_type),
        format_func=lambda code: type_labels[code], key="tree_analysis_type_input",
    )
    st.caption(type_help[analysis["type"]])

    objective_options = ["maximize", "minimize"]
    objective_labels = {
        "maximize": T["effect_objective_maximize"],
        "minimize": T["effect_objective_minimize"],
    }
    current_objective = analysis.get("effect_objective", "maximize")
    if current_objective not in objective_options:
        current_objective = "maximize"
    analysis["effect_objective"] = st.selectbox(
        T["effect_objective"], objective_options, index=objective_options.index(current_objective),
        format_func=lambda code: objective_labels[code], key="tree_analysis_objective_input",
    )

    branch_labels: list[str] = []
    for node in document.get("nodes", []):
        if node.get("type") == "decision":
            branch_labels = [branch.get("label") for branch in node.get("branches", []) if branch.get("label")]
            break
    baseline_options = ["__auto__"] + branch_labels
    baseline_labels = {"__auto__": T["baseline_strategy_auto"]}
    for label in branch_labels:
        baseline_labels[label] = label
    current_baseline = analysis.get("baseline_strategy_id") or "__auto__"
    if current_baseline not in baseline_options:
        current_baseline = "__auto__"
    chosen_baseline = st.selectbox(
        T["baseline_strategy"], baseline_options, index=baseline_options.index(current_baseline),
        format_func=lambda sid: baseline_labels.get(sid, sid), key="tree_analysis_baseline_input",
    )
    analysis["baseline_strategy_id"] = None if chosen_baseline == "__auto__" else chosen_baseline

    cost_id, effect_id, cost_symbol, cost_decimals, effect_symbol, effect_decimals = _tree_analysis_outcome_selection(
        T, document, analysis
    )

    if analysis["type"] == "CEA":
        analysis["willingness_to_pay"] = st.number_input(
            T["willingness_to_pay_label"], min_value=0.0,
            value=float(analysis.get("willingness_to_pay", 50000.0)), step=1000.0,
            key="tree_analysis_wtp_input",
        )

    _render_tree_risk_preference(document, analysis)

    st.markdown(f"**{T['analysis_preview_title']}**")
    totals = _tree_preview_totals(document, allow_negative)
    if not totals:
        st.caption(T["analysis_preview_incomplete"])
        return

    cost_values = {sid: _tree_outcome_value(values, cost_id, "cost") for sid, values in totals.items()}
    effect_values = {sid: _tree_outcome_value(values, effect_id, "effect") for sid, values in totals.items()}

    maximize = analysis["effect_objective"] == "maximize"
    direction = 1.0 if maximize else -1.0
    baseline_id = analysis["baseline_strategy_id"]
    if baseline_id not in totals:
        baseline_id = min(totals, key=lambda sid: cost_values[sid])
    wtp = float(analysis.get("willingness_to_pay", 0.0))
    analysis_type = analysis["type"]

    if analysis_type in ("CMA", "CBA"):
        _render_cma_cba_preview(
            T, analysis, analysis_type, {sid: values["name"] for sid, values in totals.items()},
            cost_values, effect_values, cost_symbol, cost_decimals, effect_symbol, effect_decimals,
            baseline_id, "tree",
        )
        return

    if analysis_type == "EV":
        rows = [
            {
                T["strategy_name"]: values["name"],
                f"{T['total_cost']} ({cost_symbol})": f"{cost_values[sid]:,.{cost_decimals}f}",
                f"{T['total_effect']} ({effect_symbol})": f"{effect_values[sid]:,.{effect_decimals}f}",
            }
            for sid, values in totals.items()
        ]
        _blue_header_table(pd.DataFrame(rows))
        best_id = max(totals, key=lambda sid: direction * effect_values[sid])
        st.success(T["analysis_preview_best"].format(name=totals[best_id]["name"]))
        return

    if analysis_type == "CEA":
        base_cost = cost_values[baseline_id]
        base_effect = effect_values[baseline_id]
        rows = []
        chart_rows = []
        qualifying: list[tuple[str, float]] = []
        for strategy_id, values in totals.items():
            incremental_cost = cost_values[strategy_id] - base_cost
            incremental_effect = effect_values[strategy_id] - base_effect
            if strategy_id == baseline_id:
                icer_text = "-"
            elif incremental_effect == 0 or (direction * incremental_effect) <= 0:
                icer_text = T["dominated"]
            else:
                icer = incremental_cost / incremental_effect
                icer_text = f"{icer:,.{cost_decimals}f}"
                if icer <= wtp:
                    qualifying.append((strategy_id, icer))
            rows.append({
                T["strategy_name"]: values["name"],
                f"{T['total_cost']} ({cost_symbol})": f"{cost_values[strategy_id]:,.{cost_decimals}f}",
                f"{T['total_effect']} ({effect_symbol})": f"{effect_values[strategy_id]:,.{effect_decimals}f}",
                T["incremental_cost"]: f"{incremental_cost:,.{cost_decimals}f}",
                T["incremental_effect"]: f"{incremental_effect:,.{effect_decimals}f}",
                f"{T['icer']} ({cost_symbol}/{effect_symbol})": icer_text,
            })
            chart_rows.append({
                T["strategy_name"]: values["name"],
                T["incremental_effect"]: incremental_effect,
                T["incremental_cost"]: incremental_cost,
            })
        _blue_header_table(pd.DataFrame(rows))

        chart_df = pd.DataFrame(chart_rows)
        if len(chart_df) >= 1:
            scatter = alt.Chart(chart_df).mark_circle(size=120).encode(
                x=alt.X(T["incremental_effect"], type="quantitative"),
                y=alt.Y(T["incremental_cost"], type="quantitative"),
                tooltip=list(chart_df.columns),
                color=alt.Color(T["strategy_name"], type="nominal", legend=None),
            )
            x_max = max((abs(v) for v in chart_df[T["incremental_effect"]].tolist()), default=0.0) or 1.0
            line_df = pd.DataFrame({
                T["incremental_effect"]: [-x_max, x_max],
                T["incremental_cost"]: [-x_max * wtp, x_max * wtp],
            })
            wtp_line = alt.Chart(line_df).mark_line(strokeDash=[4, 4], color="#94a3b8").encode(
                x=alt.X(T["incremental_effect"], type="quantitative"),
                y=alt.Y(T["incremental_cost"], type="quantitative"),
            )
            st.altair_chart(wtp_line + scatter, use_container_width=True)

        best_id = min(qualifying, key=lambda pair: pair[1])[0] if qualifying else baseline_id
        st.success(T["analysis_preview_best"].format(name=totals[best_id]["name"]))
        return

    nmb_values: dict[str, float] = {
        strategy_id: direction * wtp * effect_values[strategy_id] - cost_values[strategy_id]
        for strategy_id in totals
    }
    rows = [
        {
            T["strategy_name"]: values["name"],
            f"{T['total_cost']} ({cost_symbol})": f"{cost_values[strategy_id]:,.{cost_decimals}f}",
            f"{T['total_effect']} ({effect_symbol})": f"{effect_values[strategy_id]:,.{effect_decimals}f}",
            f"NMB ({cost_symbol})": f"{nmb_values[strategy_id]:,.{cost_decimals}f}",
        }
        for strategy_id, values in totals.items()
    ]
    _blue_header_table(pd.DataFrame(rows))
    best_nmb = max(nmb_values.values())
    chart_df = pd.DataFrame(rows)
    nmb_column = f"NMB ({cost_symbol})"
    bar = alt.Chart(chart_df).mark_bar().encode(
        x=alt.X(T["strategy_name"], type="nominal", sort="-y"),
        y=alt.Y(nmb_column, type="quantitative"),
        color=alt.condition(alt.datum[nmb_column] == best_nmb, alt.value("#16a34a"), alt.value("#94a3b8")),
        tooltip=list(chart_df.columns),
    )
    st.altair_chart(bar, use_container_width=True)
    best_id = max(nmb_values, key=lambda sid: nmb_values[sid])
    st.success(T["analysis_preview_best"].format(name=totals[best_id]["name"]))


def show_results(allow_negative: bool, document: dict[str, Any] | None = None) -> None:
    """Resolve, run, and render the ICER/NMB results table + chart for a
    flat Tree-shaped document (root_id/nodes). Defaults to Tree's own
    st.session_state.document; PSM passes st.session_state.psm_document,
    reusing this unchanged since a PSM node is just another Node -- the same rollback,
    the same per-strategy incremental comparison, the same chart."""

    if document is None:
        document = st.session_state.document
    cost_decimals, effect_decimals = _markov_decimal_places(document)
    missing_items: list[str] = []
    for node in document.get("nodes", []):
        if node.get("type") == "decision":
            continue  # strategy branches take no cost/effect input
        for branch in node.get("branches", []):
            branch_label = branch.get("label") or branch.get("child_id", "")
            if "cost_increment" not in branch:
                missing_items.append(f"{branch_label}: \\$")
            if "effect_increment" not in branch and not document.get("effect_disabled"):
                missing_items.append(f"{branch_label}: E")
    if missing_items:
        st.error(T["missing_cost_effect_error"].format(items="; ".join(missing_items)))
        return

    try:
        tree, parameters = resolve(document)
    except ValueError as exc:
        st.error(T["tree_error"].format(error=exc))
        return
    cost_rate, effect_rate = _tree_discount_rates(document)
    outcome_kinds = _tree_extra_outcome_kinds(document)
    tree_distributions = {
        str(raw["name"]): raw for raw in document.get("distributions", []) if raw.get("name")
    }
    tree_tables = build_tables_mapping(document.get("tables"))
    result = Engine().run(
        tree, parameters, allow_negative_cost=allow_negative,
        cost_discount_rate=cost_rate, effect_discount_rate=effect_rate,
        outcome_kinds=outcome_kinds,
        distributions=tree_distributions, tables=tree_tables,
    )
    for error in result.errors:
        suffix = f" ({error.node_id})" if error.node_id else ""
        st.warning(f"[{error.code}] {error.message}{suffix}")
    if not result.strategies:
        return
    st.subheader(T["results"])
    cost_symbol = document.get("cost_symbol") or "$"
    effect_symbol = document.get("effect_symbol") or "E"
    extra_outcome_rows = [
        row for row in ensure_document_outcomes(document)
        if row["type"] in ("cost", "effect") and row["id"] not in ("cost", "effect")
    ]
    columns = st.columns(len(result.strategies))
    for column, (label, strategy) in zip(columns, result.strategies.items()):
        with column:
            st.metric(
                label,
                f"{cost_symbol} {strategy.cost:,.{cost_decimals}f}",
                f"{effect_symbol}: {strategy.effect:.{effect_decimals}f}",
            )
            for extra in extra_outcome_rows:
                extra_value = strategy.extra_totals.get(extra["id"], 0.0)
                extra_label = extra.get("label") or extra["id"]
                st.caption(f"{extra_label}: {extra['symbol']} {extra_value:,.{int(extra.get('decimals', 2))}f}")
    if document is st.session_state.document:
        _render_tree_path_results(
            document, tree, parameters, cost_rate, effect_rate,
            outcome_kinds, tree_distributions, tree_tables, result,
        )
    else:
        with st.expander(T["paths"]):
            for label, strategy in result.strategies.items():
                st.markdown(f"**{label}**")
                for path in strategy.paths:
                    st.code(" → ".join(path))


def _build_tree_transparency_workbook_for_document(
    document: dict[str, Any],
    tree: Any,
    parameters: Any,
    rows: list[Any],
    cost_rate: float,
    effect_rate: float,
    result: Any,
) -> bytes:
    """Assemble the arguments build_tree_transparency_workbook() needs from
    the app's own session state -- same baseline/WTP/objective settings the
    on-screen ICER table under 'Analysis' uses (see
    _render_tree_analysis_section), so the workbook's ICER sheet reconciles
    with what the user sees in the app for the same model."""

    analysis = _markov_ensure_analysis_settings(document)
    maximize_effect = analysis.get("effect_objective", "maximize") == "maximize"
    willingness_to_pay = float(analysis.get("willingness_to_pay", 0.0))

    baseline_strategy = analysis.get("baseline_strategy_id")
    if baseline_strategy not in result.strategies:
        # "Auto" (or a baseline that no longer exists): same fallback the
        # live Analysis preview uses -- the cheapest strategy.
        baseline_strategy = min(
            result.strategies, key=lambda label: float(result.strategies[label].cost or 0.0)
        ) if result.strategies else None

    extra_outcome_labels = {
        row["id"]: row.get("label") or row["id"]
        for row in ensure_document_outcomes(document)
        if row.get("type") in ("cost", "effect") and row["id"] not in ("cost", "effect")
    }

    return build_tree_transparency_workbook(
        tree, parameters, rows,
        cost_discount_rate=cost_rate,
        effect_discount_rate=effect_rate,
        model_name=document.get("name") or "Decision Tree model",
        engine_version="",
        baseline_strategy=baseline_strategy,
        maximize_effect=maximize_effect,
        willingness_to_pay=willingness_to_pay,
        extra_outcome_labels=extra_outcome_labels,
        distributions={str(raw["name"]): raw for raw in document.get("distributions", []) if raw.get("name")},
        tables=build_tables_mapping(document.get("tables")),
    )


def _build_tree_report_for_document(
    document: dict[str, Any],
    parameters: Any,
    rows: list[Any],
    cost_rate: float,
    effect_rate: float,
    result: Any,
    symbols: dict[str, str],
    decimals: dict[str, int],
) -> "tree_report.TreeReportBundle":
    """Assemble a tree_report.TreeReportInput from the app's own session
    state -- same baseline/WTP/objective settings
    _build_tree_transparency_workbook_for_document uses above, so the
    Technical Documentation Report's Results table reconciles with both
    the on-screen Analysis view and the transparency Excel export for the
    same model."""

    analysis = _markov_ensure_analysis_settings(document)
    maximize_effect = analysis.get("effect_objective", "maximize") == "maximize"
    willingness_to_pay = float(analysis.get("willingness_to_pay", 0.0))

    baseline_strategy = analysis.get("baseline_strategy_id")
    if baseline_strategy not in result.strategies:
        # "Auto" (or a baseline that no longer exists): same fallback the
        # live Analysis preview uses -- the cheapest strategy.
        baseline_strategy = min(
            result.strategies, key=lambda label: float(result.strategies[label].cost or 0.0)
        ) if result.strategies else None

    extra_outcome_labels = {
        row["id"]: row.get("label") or row["id"]
        for row in ensure_document_outcomes(document)
        if row.get("type") in ("cost", "effect") and row["id"] not in ("cost", "effect")
    }

    strategy_order: list[str] = []
    for row in rows:
        if row.strategy not in strategy_order:
            strategy_order.append(row.strategy)

    strategy_totals: dict[str, dict[str, float]] = {}
    for strategy_label, strategy_result in result.strategies.items():
        totals = {"cost": float(strategy_result.cost or 0.0), "effect": float(strategy_result.effect or 0.0)}
        totals.update({key: float(value) for key, value in strategy_result.extra_totals.items()})
        strategy_totals[strategy_label] = totals

    report_input = tree_report.TreeReportInput(
        analysis_settings=dict(analysis),
        model_name=document.get("name") or "Decision Tree model",
        document=document,
        parameters=parameters,
        paths=rows,
        strategy_order=strategy_order,
        strategy_totals=strategy_totals,
        cost_symbol=symbols.get("cost", "$"),
        effect_symbol=symbols.get("effect", ""),
        cost_decimals=decimals.get("cost", 2),
        effect_decimals=decimals.get("effect", 3),
        extra_outcome_labels=extra_outcome_labels,
        baseline_strategy=baseline_strategy,
        maximize_effect=maximize_effect,
        willingness_to_pay=willingness_to_pay,
        cost_discount_rate=cost_rate,
        effect_discount_rate=effect_rate,
        engine_version="",
        diagram_png=st.session_state.get("tree_diagram_png"),
    )
    return tree_report.build_tree_report(report_input)


def _build_psm_report_for_document(
    document: dict[str, Any],
    tree: Any,
    parameters: Any,
    rows: list[Any],
    cost_rate: float,
    effect_rate: float,
    result: Any,
    symbols: dict[str, str],
    decimals: dict[str, int],
) -> "psm_report.TreeReportBundle":
    """Technical Documentation Report for the PSM editor (psm_report.build_psm_report): same baseline/WTP
    settings as the Analysis view, plus the tree/distributions/tables the PSM replay and self-checks need."""

    analysis = _markov_ensure_analysis_settings(document)
    baseline_strategy = analysis.get("baseline_strategy_id")
    if baseline_strategy not in result.strategies:
        baseline_strategy = min(
            result.strategies, key=lambda label: float(result.strategies[label].cost or 0.0)
        ) if result.strategies else None
    extra_outcome_labels = {
        row["id"]: row.get("label") or row["id"]
        for row in ensure_document_outcomes(document)
        if row.get("type") in ("cost", "effect") and row["id"] not in ("cost", "effect")
    }
    strategy_order: list[str] = []
    for row in rows:
        if row.strategy not in strategy_order:
            strategy_order.append(row.strategy)
    strategy_totals: dict[str, dict[str, float]] = {}
    for strategy_label, strategy_result in result.strategies.items():
        totals = {"cost": float(strategy_result.cost or 0.0), "effect": float(strategy_result.effect or 0.0)}
        totals.update({key: float(value) for key, value in strategy_result.extra_totals.items()})
        strategy_totals[strategy_label] = totals
    report_input = psm_report.PSMReportInput(
        analysis_settings=dict(analysis),
        model_name=document.get("name") or "Partitioned survival model",
        document=document,
        parameters=parameters,
        paths=rows,
        strategy_order=strategy_order,
        strategy_totals=strategy_totals,
        cost_symbol=symbols.get("cost", "$"),
        effect_symbol=symbols.get("effect", ""),
        cost_decimals=decimals.get("cost", 2),
        effect_decimals=decimals.get("effect", 3),
        extra_outcome_labels=extra_outcome_labels,
        baseline_strategy=baseline_strategy,
        maximize_effect=analysis.get("effect_objective", "maximize") == "maximize",
        willingness_to_pay=float(analysis.get("willingness_to_pay", 0.0)),
        cost_discount_rate=cost_rate,
        effect_discount_rate=effect_rate,
        engine_version="",
        diagram_png=st.session_state.get("psm_diagram_png"),
        tree=tree,
        distributions={str(raw["name"]): raw for raw in document.get("distributions", []) if raw.get("name")},
        tables=build_tables_mapping(document.get("tables")),
    )
    return psm_report.build_psm_report(report_input)


def _render_psm_documentation_downloads(document: dict[str, Any]) -> None:
    """PSM editor, under Base case results: per-path table (paths ending at a PSM node), the live-formula
    transparency Excel (one sheet per PSM node) and the Technical Documentation Report (Word + Excel)."""

    try:
        tree, parameters = resolve(document)
        cost_rate, effect_rate = _tree_discount_rates(document)
        outcome_kinds = _tree_extra_outcome_kinds(document)
        distributions = {str(raw["name"]): raw for raw in document.get("distributions", []) if raw.get("name")}
        tables = build_tables_mapping(document.get("tables"))
        result = Engine().run(
            tree, parameters, cost_discount_rate=cost_rate, effect_discount_rate=effect_rate,
            outcome_kinds=outcome_kinds, distributions=distributions, tables=tables,
        )
        if not result.strategies:
            return
        rows = tree_enumerate_paths(tree, parameters, None, distributions, cost_rate, effect_rate, outcome_kinds, tables)
    except Exception as exc:  # noqa: BLE001 -- never let documentation crash the results panel
        st.caption(f"Documentation exports unavailable: {exc}")
        return
    outcome_ids, symbols, decimals = _tree_path_outcomes(document)
    st.markdown("**Documentation exports**")
    with st.expander("Paths (each strategy's route to its PSM node)"):
        st.dataframe(pd.DataFrame(tree_paths_to_records(rows, outcome_ids, symbols)), use_container_width=True, hide_index=True)
    xlsx_col, docx_col, report_xlsx_col = st.columns(3)
    try:
        workbook_bytes = _build_tree_transparency_workbook_for_document(
            document, tree, parameters, rows, cost_rate, effect_rate, result,
        )
    except Exception as exc:  # noqa: BLE001
        st.caption(f"Transparency Excel unavailable: {exc}")
    else:
        with xlsx_col:
            st.download_button(
                "Model transparency Excel", workbook_bytes, "psm-model-transparency.xlsx",
                "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                use_container_width=True, key="psm_transparency_xlsx",
            )
    try:
        report_bundle = _build_psm_report_for_document(
            document, tree, parameters, rows, cost_rate, effect_rate, result, symbols, decimals,
        )
    except Exception as exc:  # noqa: BLE001
        st.caption(f"Technical Documentation Report unavailable: {exc}")
    else:
        with docx_col:
            st.download_button(
                "Technical Report (Word)", report_bundle.docx_bytes, f"{report_bundle.filename_stem}.docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                use_container_width=True, key="psm_report_docx",
            )
        with report_xlsx_col:
            st.download_button(
                "Technical Report (Excel)", report_bundle.xlsx_bytes, f"{report_bundle.filename_stem}.xlsx",
                "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                use_container_width=True, key="psm_report_xlsx",
            )


def _render_psm_results_panel(document: dict[str, Any]) -> None:
    show_results(allow_negative=False, document=document)
    _render_psm_documentation_downloads(document)


def _render_tree_path_results(
    document: dict[str, Any],
    tree: Any,
    parameters: Any,
    cost_rate: float,
    effect_rate: float,
    outcome_kinds: dict[str, str],
    distributions: dict[str, Any],
    tables: Any,
    result: Any,
) -> None:
    """Tree Editor only: the "Paths" section of Base case results. One row
    per root-to-terminal path (strategy branch label -> chance branch
    labels, no node names) with joint probability p and the path's total
    cost/effect, undiscounted and discounted, plus two CSV downloads: one
    row per path, and a step-by-step trace. Also stores the rows so the
    canvas can show each path's payoff next to its terminal node.

    Every number comes from tree_paths.enumerate_paths(), which reuses the
    engine's own helpers; the check below confirms sum(p x value) equals
    the strategy totals Run just reported."""

    try:
        rows = tree_enumerate_paths(
            tree, parameters, None, distributions,
            cost_rate, effect_rate, outcome_kinds, tables,
        )
    except (ValueError, TypeError) as exc:
        st.warning(f"Paths could not be listed: {exc}")
        return

    outcome_ids, symbols, decimals = _tree_path_outcomes(document)
    signature = _tree_document_signature(document)
    previous = st.session_state.get("tree_path_results")
    strategy_totals: dict[str, dict[str, float]] = {}
    for strategy_label, strategy_result in result.strategies.items():
        totals = {"cost": float(strategy_result.cost or 0.0), "effect": float(strategy_result.effect or 0.0)}
        totals.update({key: float(value) for key, value in strategy_result.extra_totals.items()})
        strategy_totals[strategy_label] = totals
    st.session_state["tree_path_results"] = {
        "signature": signature, "rows": rows, "ids": outcome_ids,
        "symbols": symbols, "decimals": decimals, "strategies": strategy_totals,
    }
    # The canvas above was already drawn this run, from the previous
    # results: redraw once so its payoffs match what was just computed.
    if (
        previous is None
        or previous.get("signature") != signature
        or previous.get("ids") != outcome_ids
        or "strategies" not in previous  # results saved by an older version of this code
    ):
        st.rerun()

    legacy_inputs = _tree_strategy_branch_legacy_inputs(document)
    if legacy_inputs:
        st.warning(
            "Strategy branches no longer take Cost/Effect input, but these still hold values from an "
            "older model and are still counted in the results: "
            + "; ".join(f"{label} ({values})" for label, values in legacy_inputs)
            + ". Clear them to make each strategy's totals come only from the nodes below it."
        )
        if st.button("Clear strategy-branch Cost/Effect", key="tree_clear_strategy_inputs"):
            _clear_tree_strategy_branch_inputs(document)
            st.rerun()

    with st.expander(T["paths"], expanded=True):
        # Self-check against Run: expected cost/effect per strategy.
        mismatches = []
        for outcome_id, attribute in (("cost", "cost"), ("effect", "effect")):
            if outcome_id not in outcome_ids:
                continue
            expected = {}
            for row in rows:
                expected[row.strategy] = expected.get(row.strategy, 0.0) + row.p * row.discounted.get(outcome_id, 0.0)
            for label, strategy in result.strategies.items():
                if abs(expected.get(label, 0.0) - float(getattr(strategy, attribute) or 0.0)) > 1e-6 * max(1.0, abs(expected.get(label, 0.0))):
                    mismatches.append(f"{label} ({symbols[outcome_id]})")
        if mismatches:
            st.warning("Path totals do not reconcile with the strategy results for: " + ", ".join(mismatches))

        records = tree_paths_to_records(rows, outcome_ids, symbols)
        if not records:
            st.caption("No paths.")
            return
        frame = pd.DataFrame(records)
        st.dataframe(frame, use_container_width=True, hide_index=True)
        trace_frame = pd.DataFrame(tree_trace_to_records(rows, outcome_ids, symbols))
        download_paths_col, download_trace_col, download_xlsx_col = st.columns(3)
        with download_paths_col:
            st.download_button(
                "Paths CSV", frame.to_csv(index=False).encode("utf-8-sig"),
                "tree-paths.csv", "text/csv", use_container_width=True, key="tree_paths_csv",
            )
        with download_trace_col:
            st.download_button(
                "Trace CSV (step by step)", trace_frame.to_csv(index=False).encode("utf-8-sig"),
                "tree-paths-trace.csv", "text/csv", use_container_width=True, key="tree_paths_trace_csv",
            )
        with download_xlsx_col:
            try:
                workbook_bytes = _build_tree_transparency_workbook_for_document(
                    document, tree, parameters, rows, cost_rate, effect_rate, result,
                )
            except Exception as exc:  # noqa: BLE001 -- never let the export crash the page
                st.caption(f"Transparency Excel unavailable: {exc}")
            else:
                st.download_button(
                    "Model transparency Excel", workbook_bytes,
                    "tree-model-transparency.xlsx",
                    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    use_container_width=True, key="tree_transparency_xlsx",
                )

        report_docx_col, report_xlsx_col = st.columns(2)
        try:
            report_bundle = _build_tree_report_for_document(
                document, parameters, rows, cost_rate, effect_rate, result, symbols, decimals,
            )
        except Exception as exc:  # noqa: BLE001 -- never let the report crash the page
            st.caption(f"Technical Documentation Report unavailable: {exc}")
        else:
            with report_docx_col:
                st.download_button(
                    "Technical Documentation Report (Word)", report_bundle.docx_bytes,
                    f"{report_bundle.filename_stem}.docx",
                    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                    use_container_width=True, key="tree_report_docx",
                )
            with report_xlsx_col:
                st.download_button(
                    "Technical Documentation Report (Excel)", report_bundle.xlsx_bytes,
                    f"{report_bundle.filename_stem}.xlsx",
                    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                    use_container_width=True, key="tree_report_xlsx",
                )
            if not st.session_state.get("tree_diagram_png"):
                st.caption(
                    "Tip: click the camera button on the canvas above, then reopen this section, to "
                    "include the tree diagram in the Word report."
                )


