def markov_active_strategy() -> dict[str, Any]:
    """Return the currently active strategy's dict (states/transitions),
    self-healing st.session_state.markov_active_strategy_id if it points
    at a strategy that no longer exists (e.g. it was just deleted)."""

    document = st.session_state.markov_document
    strategies = document.setdefault("strategies", [])
    if not strategies:
        strategies.append({"id": "strategy_1", "name": "Strategy 1", "states": [], "transitions": []})
    active_id = st.session_state.get("markov_active_strategy_id")
    for strategy in strategies:
        if strategy["id"] == active_id:
            return strategy
    _markov_set_active_strategy(strategies[0]["id"])
    return strategies[0]


def markov_active_positions() -> dict[str, tuple[float, float]]:
    """Canvas positions for the active strategy's own tree, namespaced by
    strategy id inside st.session_state.markov_positions (a dict of
    dicts) so switching strategies never mixes up node coordinates.
    Decision-level nodes (the decision node and each strategy's root)
    live under the separate "__decision__" namespace."""

    strategy_id = markov_active_strategy()["id"]
    return st.session_state.markov_positions.setdefault(strategy_id, {})


def _markov_set_active_strategy(strategy_id: str) -> None:
    """Set the active strategy id. Also bumps a version counter used in
    the Strategies radio widget's key: st.radio's `index=` argument is
    only honored the first time a given key renders, and writing
    directly into an already-instantiated widget's session_state slot
    raises StreamlitWidgetAlreadyInstantiatedError -- so instead, every
    programmatic switch (Add strategy, Delete strategy, clicking a
    collapsed strategy root) gives the radio a fresh key next render,
    which makes it honor `index=` again instead of a possibly-stale
    stored value."""

    st.session_state.markov_active_strategy_id = strategy_id
    st.session_state.markov_strategy_radio_version = (
        st.session_state.get("markov_strategy_radio_version", 0) + 1
    )


MARKOV_DECISION_ID = "__markov_decision__"
_MARKOV_STRATEGY_ROOT_PREFIX = "__markov_strategy_root__"


def _markov_strategy_root_id(strategy_id: str) -> str:
    return f"{_MARKOV_STRATEGY_ROOT_PREFIX}{strategy_id}"


def markov_state_map() -> dict[str, dict[str, Any]]:
    return {state["id"]: state for state in markov_active_strategy().get("states", [])}


MARKOV_ROOT_ID = "__markov_root__"

def _markov_depth_x(depth: int) -> float:
    """Horizontal offset (from the strategy root's own column) for a
    state at this canvas_parent depth. Every nesting generation
    ("double-click / add node as a child") sits exactly LAYOUT_X_SPACING
    away from its parent, same as the main Decision/Root/State/Leaf
    columns, so every branch line is the same length no matter how deep
    it's nested. (A previous change gave deeper generations a smaller
    step -- MARKOV_CHILD_X_SPACING -- to stop very deep chains from
    sprawling right after Auto-arrange, but that also made newly-added
    nested branch lines visibly shorter than the rest of the canvas,
    which looked inconsistent -- reverted in favor of uniform
    spacing. Shared by both the Markov and Microsim canvases, which both
    call this via _markov_tree_layout().)"""

    return LAYOUT_X_SPACING * (depth + 1)


def _markov_leaf_id(from_state: str, to_state: str, occurrence: int) -> str:
    """Deterministic canvas id for one outgoing transition's terminal
    leaf, unique even when several transitions share the same
    (from, to) pair."""

    return f"__leaf__{from_state}__{to_state}__{occurrence}"


def _markov_transition_index(strategy: dict[str, Any], transition: dict[str, Any]) -> int | None:
    """Find `transition`'s index in strategy["transitions"] by identity
    (not equality), so a canvas edge's "editable" payload can point back
    at exactly the transition it was drawn from and stay unambiguous
    even if two transitions happen to look identical."""

    for index, candidate in enumerate(strategy.get("transitions", [])):
        if candidate is transition:
            return index
    return None


def _markov_outgoing_by_state(document: dict[str, Any]) -> dict[str, list[dict[str, Any]]]:
    """Group this Markov document's transitions by their from_state,
    keeping only transitions whose from_state is an actual state
    (defensive against a stale/edited document)."""

    state_ids = {state["id"] for state in document.get("states", [])}
    by_state: dict[str, list[dict[str, Any]]] = {}
    for transition in document.get("transitions", []):
        from_state = transition.get("from_state")
        if from_state in state_ids:
            by_state.setdefault(from_state, []).append(transition)
    return by_state


def _markov_local_probability_group_error(entries: list[Any]) -> bool:
    """Cheap, resolution-free check for an obviously broken outgoing (or
    initial-occupancy) probability group on the Markov canvas -- same
    rules as markov_validation._check_probability_group(), but skips
    anything that needs parameter/expression resolution, since this
    runs on every canvas redraw (every click/drag), not just on Run:
    more than one "#" complement, a negative numeric entry, or (only
    when EVERY entry in the group is a plain number -- no "#", no
    parameter name, no formula) a sum that isn't ~1. A group containing
    a parameter name or formula string can't be checked locally, so it
    is left unflagged rather than risking a false "orange" on a
    perfectly valid model (false positives are worse than a
    missed one here, since users learn to distrust the highlight)."""

    if not entries:
        return False
    complement_count = 0
    numeric_sum = 0.0
    has_unresolvable = False
    for value in entries:
        if isinstance(value, str) and value.strip() == "#":
            complement_count += 1
            continue
        if isinstance(value, bool):
            has_unresolvable = True
            continue
        if isinstance(value, (int, float)):
            if value < 0:
                return True
            numeric_sum += float(value)
            continue
        has_unresolvable = True
    if complement_count > 1:
        return True
    if complement_count == 1:
        return numeric_sum > 1.0 + 1e-6
    if has_unresolvable:
        return False
    return abs(numeric_sum - 1.0) > 1e-6


def _markov_canvas_kind(state: dict[str, Any], outgoing: list[dict[str, Any]]) -> str:
    """Return a stable canvas kind; layout must never change node shape."""

    explicit_kind = state.get("canvas_kind")
    if explicit_kind in {"chance", "markov"}:
        return "chance"
    if explicit_kind in {"terminal", "decision", "root", "psm"}:
        return explicit_kind
    has_complement_self_loop = any(
        transition.get("from_state") == state.get("id")
        and transition.get("to_state") == state.get("id")
        and str(transition.get("probability", "")).strip() in {"#", "C", "c"}
        for transition in outgoing
    )
    if has_complement_self_loop and not state.get("is_absorbing", False):
        state["canvas_kind"] = "chance"
        return "chance"
    return "chance" if outgoing else "terminal"


def _markov_tree_layout(
    strategy: dict[str, Any],
    dragged_positions: dict[str, tuple[float, float]] | None = None,
) -> dict[str, tuple[float, float]]:
    """Compute a TreeAge-style tree layout for the Markov canvas, using
    the SAME recursive depth/sibling-centering convention as the
    Decision Tree canvas's own auto_layout(): a state's x position
    reflects how many "double-click / add node as a child" generations
    deep it is, not a single flat column for every state regardless of
    how it was created.

    A state's layout depth comes from its own "canvas_parent" field
    (set by add_markov_canvas_state() when it was created as a specific
    node's child -- see the quick_branch and add_node canvas events).
    A state with no canvas_parent -- every state loaded from a file,
    and every state added directly under the strategy root or the
    decision node -- is top-level (depth 0), exactly like every state
    was positioned before this function became depth-aware. Every
    state still gets one leaf per outgoing transition (one per cycle
    destination, "the cohort ends up in this state next cycle"),
    including transitions whose target is also a canvas_parent-child of
    this state -- the leaf and the nested state are two different
    things (a transition marker vs. the state's own node) and both are
    always drawn.

    dragged_positions (raw id -> (x, y), the strategy's own slice of
    st.session_state.markov_positions right before a re-layout) lets a
    state's own leaves and canvas-child states be stacked top-to-bottom
    by wherever the user last dragged them on the canvas, falling back
    to their original order for anything never dragged -- mirrors the
    Decision Tree's own auto_layout() sibling-sort, so "drag a branch
    above its sibling, then press Auto-arrange" now behaves the same
    way in both editors instead of Markov always snapping back to a
    fixed order."""

    dragged_positions = dragged_positions or {}
    states = {state["id"]: state for state in strategy.get("states", [])}
    outgoing_by_state = _markov_outgoing_by_state(strategy)

    children_of: dict[str, list[str]] = {}
    top_level: list[str] = []
    for state_id, state in states.items():
        parent = state.get("canvas_parent")
        if parent and parent in states and parent != state_id:
            children_of.setdefault(parent, []).append(state_id)
        else:
            top_level.append(state_id)
    top_level = [
        state_id
        for _, state_id in sorted(
            enumerate(top_level),
            key=lambda item: dragged_positions.get(item[1], (0.0, float(item[0])))[1],
        )
    ]

    positions: dict[str, tuple[float, float]] = {}
    next_y = [LAYOUT_START_Y]
    visited: set[str] = set()
    leaf_heights: dict[str, float] = {}
    label_chars, value_chars, _text_scale = _canvas_text_metrics(None, LAYOUT_X_SPACING - 68)

    def place(state_id: str, depth: int) -> float:
        visited.add(state_id)
        outgoing = outgoing_by_state.get(state_id, [])
        occurrence_counts: dict[tuple[str, str], int] = {}
        leaf_order: list[str] = []
        for transition in outgoing:
            to_state = transition.get("to_state")
            target_state = states.get(to_state)
            if target_state is not None and target_state.get("canvas_parent") == state_id:
                # Promoted to a real child node below (see
                # markov_canvas_payload's promoted_transition_by_state) --
                # not drawn as a generic terminal leaf, so it must not
                # eat a Y slot or skew the centering average either.
                continue
            key = (state_id, to_state)
            occurrence_counts[key] = occurrence_counts.get(key, 0) + 1
            leaf_id = _markov_leaf_id(state_id, to_state, occurrence_counts[key])
            leaf_order.append(leaf_id)
            # Room for the (wrapped) branch label above the line and the p= / Incre_$= /
            # Incre_E= rows below it, so a long expression never runs into the next leaf.
            above = _canvas_text_lines((transition.get("label") or (target_state or {}).get("name") or to_state), label_chars)
            below = _canvas_text_lines(f"p={value_text(transition.get('probability'))}", value_chars)
            below += _canvas_text_lines(f"Incre_$={value_text(transition.get('cost_increment'))}", value_chars)
            below += _canvas_text_lines(f"Incre_E={value_text(transition.get('effect_increment'))}", value_chars)
            for _extra_value in (transition.get("extra_increment") or {}).values():
                below += _canvas_text_lines(f"Incre_X={value_text(_extra_value)}", value_chars)
            leaf_heights[leaf_id] = max(LAYOUT_Y_SPACING, 14.0 * below + 14.0 * (above - 1) + 40.0)

        child_ids = [cid for cid in children_of.get(state_id, []) if cid not in visited]

        # One combined sibling list -- this state's own leaves plus its
        # canvas-child states -- sorted by dragged Y (see docstring)
        # instead of always leaves-then-children in creation order.
        combined: list[tuple[str, str]] = [("leaf", lid) for lid in leaf_order] + [
            ("child", cid) for cid in child_ids
        ]
        combined = [
            entry
            for _, entry in sorted(
                enumerate(combined),
                key=lambda item: dragged_positions.get(item[1][1], (0.0, float(item[0])))[1],
            )
        ]

        entry_ys: list[float] = []
        for kind, raw_id in combined:
            if kind == "leaf":
                y = next_y[0]
                next_y[0] += leaf_heights.get(raw_id, LAYOUT_Y_SPACING)
                positions[raw_id] = (LAYOUT_START_X + _markov_depth_x(depth) + LAYOUT_X_SPACING, y)
                entry_ys.append(y)
            else:
                entry_ys.append(place(raw_id, depth + 1))

        if entry_ys:
            y = sum(entry_ys) / len(entry_ys)
        else:
            y = next_y[0]
            next_y[0] += LAYOUT_Y_SPACING
        positions[state_id] = (LAYOUT_START_X + _markov_depth_x(depth), y)
        return y

    for state_id in top_level:
        if state_id not in visited:
            place(state_id, 0)
    # Defensive: a state that never got placed (shouldn't normally
    # happen -- every non-top-level state has a real canvas_parent by
    # construction) still gets a slot, never lost off-screen.
    for state_id in states:
        if state_id not in visited:
            place(state_id, 0)

    state_ys = [positions[state_id][1] for state_id in states if state_id in positions]
    positions[MARKOV_ROOT_ID] = (
        LAYOUT_START_X,
        sum(state_ys) / len(state_ys) if state_ys else LAYOUT_START_Y,
    )
    return positions


def _markov_subtree_state_ids(strategy: dict[str, Any], root_id: str) -> list[str]:
    """root_id plus every state that "belongs" to it as a downstream
    branch, for delete/cut/copy on the canvas: a branch always moves,
    is duplicated, or disappears as a whole, never orphaning or
    silently dropping what hangs off it.

    Two different signals count as "belongs to root_id", unioned:

    1. Canvas-nested children -- a state created directly as root_id's
       child (a double-clicked quick_branch, or "Add node" aimed
       precisely at root_id), recorded in that state's own
       canvas_parent field. This is the original signal
       _markov_tree_layout() also draws from. Always active, and
       applied recursively to every state pulled into the subtree by
       either signal.

    2. Transition-graph descendants exclusively owned by root_id -- a
       state reached by walking outgoing transitions from states
       already in the subtree, included only while it (a) has no
       OTHER inbound transition from a state outside the subtree,
       (b) isn't itself a cohort-entry state (initial_prob > 0), and
       (c) isn't a "markov"-kind state. This covers the workflow of
       wiring a chain of chance/terminal nodes together with
       add_terminal_transition (or a dragged connection) instead of
       double-clicking each one as the previous node's child, when
       that chain hangs off an explicit tree-branch node -- see the
       gate right below for when this signal is even considered.

       "markov"-kind states are deliberately never absorbed this way:
       they're the recurring Markov-chain states themselves (Healthy/
       Sick/Dead...) -- shared and cyclic, never privately owned by
       whichever branch happens to transition into them. A branch
       that transitions into one keeps that transition in the
       clipboard/deletion (see the copy_node handler), but the target
       state itself is left alone, exactly like today's handling of a
       branch feeding into a shared absorbing state.

    Signal 2 is gated on root_id itself: it only ever runs when root_id
    already has a canvas_parent, i.e. root_id is itself an explicit
    tree-branch node nested under something else (a decision fork built
    on top of the Markov canvas), not a genuine top-level/core Markov
    health state. Without this gate, copying a perfectly ordinary
    top-level chance state (Healthy/Sick/MildDisease/...) in a REAL,
    densely-interconnected Markov chain would walk the shared state
    graph and sweep in almost every other non-entry state reachable
    from it -- everything except the one protected cohort-entry state
    -- because in a cyclic chain, once enough of the cluster is
    "included", every remaining member's only outside inbound edges
    get absorbed too, and the whole model ends up copied instead of
    the single clicked state. A top-level health state simply doesn't
    have a well-defined "private branch behind it" the way a tree node
    does -- transitions between core states ARE the model, not a
    branch -- so root_id being top-level restricts the whole walk to
    signal 1 only (still fully recursive through nested canvas
    children). root_id having its own canvas_parent means the user is
    already copying from inside an explicit, previously-built branch,
    where signal 2's existing behavior (added to fix "copy only grabs
    the one node I clicked, not the branch behind it") still applies
    unrestricted, exactly as before.

    A fixed-point loop (not a single DFS pass) so two states already
    in the subtree that both feed into the same later state -- e.g.
    two sibling chance branches reconverging -- still let that state
    in once both sources are accounted for, rather than rejecting it
    because only one source had been visited so far.
    """

    states = {state["id"]: state for state in strategy.get("states", [])}
    canvas_children_of: dict[str, list[str]] = {}
    for state in states.values():
        parent = state.get("canvas_parent")
        if parent and parent in states and parent != state["id"]:
            canvas_children_of.setdefault(parent, []).append(state["id"])

    root_state = states.get(root_id, {})
    root_parent = root_state.get("canvas_parent")
    root_has_canvas_parent = bool(root_parent and root_parent in states and root_parent != root_id)

    outgoing_to: dict[str, list[str]] = {}
    inbound_from: dict[str, set[str]] = {}
    for transition in strategy.get("transitions", []):
        from_state = transition.get("from_state")
        to_state = transition.get("to_state")
        if from_state not in states or to_state not in states:
            continue
        outgoing_to.setdefault(from_state, []).append(to_state)
        if to_state != from_state:
            inbound_from.setdefault(to_state, set()).add(from_state)

    included: set[str] = {root_id}
    changed = True
    while changed:
        changed = False
        for state_id in list(included):
            for child_id in canvas_children_of.get(state_id, []):
                if child_id not in included:
                    included.add(child_id)
                    changed = True
            if not root_has_canvas_parent:
                # root_id is a genuine top-level Markov health state --
                # never chase the transition graph (see the docstring's
                # gate above); only explicit canvas-children, recursively,
                # ever come along.
                continue
            for target_id in outgoing_to.get(state_id, []):
                if target_id in included:
                    continue
                target_state = states.get(target_id, {})
                if target_state.get("canvas_kind") == "markov":
                    continue
                if float(target_state.get("initial_prob", 0.0) or 0.0) != 0.0:
                    continue
                if inbound_from.get(target_id, set()) - included:
                    # Has an inbound edge from a state outside the
                    # subtree -- shared with something else, so keep
                    # it as an external link instead of absorbing it.
                    continue
                included.add(target_id)
                changed = True

    return [state_id for state_id in states if state_id in included]


def _markov_promoted_transition_by_state(strategy: dict[str, Any]) -> dict[str, dict[str, Any]]:
    """For every state whose canvas_parent points at another real state
    in this strategy (a canvas-created child, from a double-click or a
    right-click "Add node" with that state as parent), find the
    specific parent->child transition that makes it a genuine
    canvas-tree edge -- keyed by the CHILD state's id. A state missing
    from this mapping is top-level: its one real parent is the strategy
    root itself (a real health state), not another state. Shared by
    markov_canvas_payload() (layout/is_health_state) and the Insert
    node handlers (which need to know whether a node's one real parent
    edge is the root's initial_prob edge or another state's transition)."""

    states = {state["id"]: state for state in strategy.get("states", [])}
    outgoing_by_state = _markov_outgoing_by_state(strategy)
    promoted: dict[str, dict[str, Any]] = {}
    for state in states.values():
        parent_raw_id = state.get("canvas_parent")
        if not parent_raw_id or parent_raw_id not in states or parent_raw_id == state["id"]:
            continue
        match = next(
            (t for t in outgoing_by_state.get(parent_raw_id, []) if t.get("to_state") == state["id"]),
            None,
        )
        if match is not None:
            promoted[state["id"]] = match
    return promoted


def _markov_split_composite_id(node_id: str | None) -> tuple[str | None, str | None]:
    """Split a canvas node id produced by markov_canvas_payload() back
    into (strategy_id, raw_id) -- the inverse of the
    f"{strategy_id}::{raw_id}" convention used for state/leaf nodes now
    that every strategy's tree is drawn on the shared canvas at once.
    Returns (None, None) for the decision node, a missing/None id (e.g.
    a right-click "add node" on empty canvas with no parent), and a
    strategy-root node returns (strategy_id, None)."""

    if node_id is None or node_id == MARKOV_DECISION_ID:
        return None, None
    if node_id.startswith(_MARKOV_STRATEGY_ROOT_PREFIX):
        return node_id[len(_MARKOV_STRATEGY_ROOT_PREFIX):], None
    if "::" in node_id:
        strategy_id, raw_id = node_id.split("::", 1)
        return strategy_id, raw_id
    return None, node_id


def _markov_push_undo_snapshot() -> None:
    """Snapshot the whole Markov document (every strategy) plus its
    canvas positions and current selection before a structural canvas
    edit, so the "undo" canvas event (Cmd/Ctrl+Z) can restore exactly
    what that edit changed. Capped so a long editing session never
    grows this without bound."""

    stack = st.session_state.setdefault("markov_undo_stack", [])
    stack.append(
        {
            "document": copy.deepcopy(st.session_state.markov_document),
            "positions": copy.deepcopy(st.session_state.markov_positions),
            "selected_id": st.session_state.markov_selected_id,
            "active_strategy_id": st.session_state.get("markov_active_strategy_id"),
        }
    )
    del stack[:-30]


def _wipe_model_inputs(document: dict[str, Any]) -> None:
    """Clear model = blank model: besides the canvas, empty every input table
    (Parameters, Variables, Distributions, Tables) and the dashboard cards, and
    drop the example model's citation note."""

    for key in ("parameters", "variables", "distributions", "tables", "dashboard_items"):
        if key in document:
            document[key] = []
    document.pop("note", None)


def _markov_clear_model() -> None:
    """Reset the Markov model down to just its Decision node fanning into
    one strategy with a bare Markov ("M") root and no states -- the
    "Clear model" button's target state. Only the strategy/state
    structure is reset; document-wide settings (cycles, discounting,
    cost/effect symbols, outcomes table) are left as configured.
    Snapshots the current model onto the undo stack first.

    Also drops document["note"] (2026-09-30): that field is only
    ever populated by _load_sample_markov_document() as the "Adapted
    from <publication>" citation caption for the capivasertib example
    model this editor opens with (see its own docstring) -- it describes
    the SPECIFIC states/transitions Clear model just wiped, so leaving
    it behind would keep citing a published study for a model that no
    longer resembles it. The Tree Editor's own _tree_clear_model()
    already gets this for free (it replaces st.session_state.document
    wholesale, which has no "note" key); Markov mutates specific fields
    in place instead, so the drop has to be explicit here."""

    _markov_push_undo_snapshot()
    document = st.session_state.markov_document
    document["strategies"] = [{"id": "strategy_1", "name": "Strategy 1", "states": [], "transitions": []}]
    _wipe_model_inputs(document)
    st.session_state.markov_positions = {}
    st.session_state.markov_selected_id = None
    _markov_set_active_strategy("strategy_1")
    st.session_state.markov_results_computed = False
    mark_markov_flow_changed()


def _markov_strategy_band_at(y: float) -> str:
    """Return whichever strategy's vertical band (from the layout most
    recently built by markov_canvas_payload()) a canvas y-coordinate
    falls in -- used to route a right-click "add state" on the shared
    canvas to the strategy it was clicked under. Falls back to the
    active strategy when the click lands outside every band."""

    bands = st.session_state.get("markov_strategy_bands", {})
    for strategy_id, (y_min, y_max) in bands.items():
        if y_min <= y <= y_max:
            return strategy_id
    return markov_active_strategy()["id"]


def _markov_edge_annotations(
    strategy_id: str,
    to_state_id: str,
    target_state: dict[str, Any],
    branch_label_value: Any,
    prob_locator: dict[str, Any],
    transition: dict[str, Any] | None = None,
    include_state_reward: bool = True,
) -> dict[str, Any]:
    """Build the branch-label plus ($)/(E) state-cost/state-effect display
    and editable fields shared by every Markov canvas edge that leads
    into a health-state node -- an initial-occupancy edge from the
    strategy root, or a transition edge from another state. A branch
    label is independent of the target state's own name/id (mirroring
    the Decision Tree canvas): it is stored on the transition itself
    (or, for a root->state initial-occupancy edge with no transition
    object, on the state's own "entry_label" field) and falls back to
    displaying the target state's name when unset. Cost/effect always
    reflect the TARGET STATE's single shared cost/effect fields (there
    is no per-transition reward in the Markov engine, unlike the
    Decision Tree's cost_increment/effect_increment), so editing either
    row here -- from any edge leading into that state -- writes straight
    back to the state itself."""

    branch_label_text = str(branch_label_value).strip() if branch_label_value not in (None, "") else ""
    display_label = branch_label_text or target_state.get("name") or to_state_id
    cost_decimals, effect_decimals = _markov_decimal_places(st.session_state.markov_document)
    if target_state.get("tenure_applied"):
        # Tenure states carry 3 separate cost figures (initial cycle /
        # recurring cycles / terminal cycle) instead of one flat cost --
        # show all 3 on the ($) row, e.g. "500.00 / 200.00 / 400.00" or
        # "c1 / c2 / c3" when the user typed parameter names, in the
        # same initial/recurring/terminal order as the Edit State panel.
        initial_cost_text = value_text(target_state.get("initial_cost"))
        recurring_cost_text = value_text(target_state.get("recurring_cost", target_state.get("cost")))
        terminal_cost_text = value_text(target_state.get("terminal_cost"))
        cost_text = f"{initial_cost_text} / {recurring_cost_text} / {terminal_cost_text}"
        cost_display_text = " / ".join(
            _format_outcome_value(value, cost_decimals)
            for value in (
                target_state.get("initial_cost"),
                target_state.get("recurring_cost", target_state.get("cost")),
                target_state.get("terminal_cost"),
            )
        )
    else:
        cost_text = value_text(target_state.get("cost"))
        cost_display_text = _format_outcome_value(target_state.get("cost"), cost_decimals)
    effect_text = value_text(target_state.get("effect"))
    effect_display_text = _format_outcome_value(target_state.get("effect"), effect_decimals)
    cost_symbol = st.session_state.markov_document.get("cost_symbol") or "$"
    effect_symbol = st.session_state.markov_document.get("effect_symbol") or "E"
    result = {
        "label": display_label,
        "label_editable": {**prob_locator, "type": "branch_label", "current": branch_label_text},
    }
    if include_state_reward:
        result["cost_label"] = f"{cost_symbol}={cost_display_text}"
        result["cost_current"] = cost_text
        result["cost_prompt"] = f"Cost of state ({cost_symbol})"
        result["cost_editable"] = {"strategy_id": strategy_id, "type": "state_cost", "state_id": to_state_id, "current": cost_text}
        result["effect_label"] = f"{effect_symbol}={effect_display_text}"
        result["effect_current"] = effect_text
        result["effect_prompt"] = f"Effect of state ({effect_symbol})"
        result["effect_editable"] = {"strategy_id": strategy_id, "type": "state_effect", "state_id": to_state_id, "current": effect_text}

    extra_outcome_rows = [
        row for row in ensure_document_outcomes(st.session_state.markov_document)
        if row.get("type") in ("cost", "effect") and row.get("id") not in ("cost", "effect")
    ]
    if include_state_reward and extra_outcome_rows:
        state_extra_rows = []
        for extra_row in extra_outcome_rows:
            oid = extra_row["id"]
            extra_symbol = extra_row.get("symbol") or oid
            extra_decimals = int(extra_row.get("decimals", 2) or 0)
            extra_raw_value = (target_state.get("extra_outcomes") or {}).get(oid)
            extra_text = value_text(extra_raw_value)
            extra_display_text = _format_outcome_value(extra_raw_value, extra_decimals)
            state_extra_rows.append({
                "text": f"{extra_symbol}={extra_display_text}",
                "prompt": f"{extra_row.get('label') or extra_symbol} ({extra_symbol})",
                "editable": {
                    "strategy_id": strategy_id,
                    "type": "state_extra_outcome",
                    "state_id": to_state_id,
                    "outcome_id": oid,
                    "current": extra_text,
                },
            })
        result["extra_state_rows"] = state_extra_rows
    if transition is not None and extra_outcome_rows:
        incre_extra_rows = []
        for extra_row in extra_outcome_rows:
            oid = extra_row["id"]
            extra_symbol = extra_row.get("symbol") or oid
            extra_decimals = int(extra_row.get("decimals", 2) or 0)
            incre_raw_value = (transition.get("extra_increment") or {}).get(oid)
            incre_text = value_text(incre_raw_value)
            incre_display_text = _format_outcome_value(incre_raw_value, extra_decimals)
            incre_extra_rows.append({
                "text": f"Incre_{extra_symbol}={incre_display_text}",
                "prompt": f"Incre_{extra_symbol} ({extra_row.get('label') or extra_symbol})",
                "editable": {
                    **prob_locator,
                    "type": "transition_extra_increment",
                    "outcome_id": oid,
                    "current": incre_text,
                },
            })
        result["extra_incre_rows"] = incre_extra_rows
    if transition is not None:
        # Per-transition reward (each branch is separate -- two
        # different transitions into the same shared state must be able
        # to carry different costs without the engine forcing them to
        # match, unlike the ($)/(E) row above). Prefixed "Incre_" so it
        # reads distinctly from the state's own ($)/(E) row right next
        # to it on the same edge.
        # None (key genuinely absent -- never touched by the user)
        # stays None here so _format_outcome_value/value_text show it
        # as a blank "Incre_$="/"Incre_E=" on canvas, same as a truly
        # unset state Cost/Effect -- defaulting to 0.0 here used to
        # make an untouched increment display as "0.00", indistinguishable
        # from one the user deliberately set to zero (the canvas showed 0.0 for Incre_$/Incre_E while the Edit-state panel showed them empty).
        incre_cost_value = transition.get("cost_increment")
        incre_effect_value = transition.get("effect_increment")
        incre_cost_text = value_text(incre_cost_value)
        incre_effect_text = value_text(incre_effect_value)
        incre_cost_display_text = _format_outcome_value(incre_cost_value, cost_decimals)
        incre_effect_display_text = _format_outcome_value(incre_effect_value, effect_decimals)
        result["increment_cost_label"] = f"Incre_{cost_symbol}={incre_cost_display_text}"
        result["increment_cost_current"] = incre_cost_text
        result["increment_cost_prompt"] = f"Incre_{cost_symbol} (transition cost)"
        result["increment_cost_editable"] = {
            **prob_locator,
            "type": "transition_cost_increment",
            "current": incre_cost_text,
        }
        result["increment_effect_label"] = f"Incre_{effect_symbol}={incre_effect_display_text}"
        result["increment_effect_current"] = incre_effect_text
        result["increment_effect_prompt"] = f"Incre_{effect_symbol} (transition effect)"
        result["increment_effect_editable"] = {
            **prob_locator,
            "type": "transition_effect_increment",
            "current": incre_effect_text,
        }
    return result


def markov_canvas_payload() -> tuple[list[dict], list[dict]]:
    """Build the plain node/edge dicts the custom markov_canvas component
    renders (see markov_canvas_component/frontend/index.html): a single
    decision node, and -- for EVERY strategy at once, none collapsed --
    its own Markov-root node plus its full state/chance/terminal tree
    (one node per state, chance if it has outgoing transitions, terminal
    otherwise, plus one further terminal leaf per outgoing transition).
    Every strategy's tree is always fully drawn and interactive, stacked
    one below another so they never overlap -- matching how Amua and
    TreeAge draw a multi-strategy Markov model.

    A strategy's root id is already globally unique
    (_markov_strategy_root_id embeds the strategy id); state and leaf
    ids are prefixed f"{strategy_id}::{raw_id}" so two strategies reusing
    the same raw state id (e.g. both have a "healthy" state) never
    collide on the shared canvas. markov_node_owner / markov_leaf_owner
    (both keyed by these composite/global canvas ids) and
    markov_strategy_bands (strategy id -> the (y_min, y_max) it occupies)
    are stashed in session_state so the canvas event dispatcher below can
    resolve which strategy a click, drag, or right-click belongs to."""

    document = st.session_state.markov_document
    strategies = document.get("strategies", [])

    # Real, model-blocking validation errors (missing_transitions,
    # unresolved_alias, missing_parameter, negative_cost, invalid
    # tenure_count, duplicate/unknown state references, ...) -- as
    # opposed to has_error's OTHER, cheap/local heuristic checks above
    # (missing cost/effect, an obviously-wrong probability group) which
    # never need a full resolve. This reuses the exact same cache
    # show_markov_results()'s Results tab already relies on
    # (_markov_full_results_cached), so asking for it here on every
    # canvas render is effectively free once the document stops
    # changing -- see _markov_full_results_cached's docstring for why
    # that cache exists at all.
    blocking_results_by_id = _markov_blocking_errors(document, False)

    result_totals = (
        _markov_preview_totals(document, False)
        if st.session_state.get("markov_results_computed")
        else None
    )
    result_cost_symbol = document.get("cost_symbol") or "$"
    result_effect_symbol = document.get("effect_symbol") or "E"
    result_cost_decimals, result_effect_decimals = _markov_decimal_places(document)

    decision_positions = st.session_state.markov_positions.setdefault("__decision__", {})

    nodes: list[dict] = []
    edges: list[dict] = []
    leaf_owner: dict[str, str] = {}
    leaf_transition: dict[str, tuple[str, int | None]] = {}
    node_owner: dict[str, tuple[str, str | None]] = {}
    strategy_bands: dict[str, tuple[float, float]] = {}

    root_ys: list[float] = []
    y_cursor = LAYOUT_START_Y
    show_state_numbers = bool(st.session_state.get("show_state_numbers", False))
    for strategy in strategies:
        ensure_state_numbers(strategy)
        strategy_id = strategy["id"]
        root_id = _markov_strategy_root_id(strategy_id)
        node_owner[root_id] = (strategy_id, None)

        result_label = None
        if result_totals and strategy_id in result_totals:
            strategy_total = result_totals[strategy_id]
            result_label = (
                f"{result_cost_symbol} {strategy_total['cost']:,.{result_cost_decimals}f}"
                f" | {result_effect_symbol} {strategy_total['effect']:,.{result_effect_decimals}f}"
            )

        states = {state["id"]: state for state in strategy.get("states", [])}
        outgoing_by_state = _markov_outgoing_by_state(strategy)
        stored_positions = st.session_state.markov_positions.setdefault(strategy_id, {})
        # Merge: dragged nodes keep their real pixel Y; everything else
        # gets a same-scale baseline Y from an undragged layout pass, so
        # every sibling has a directly comparable position to sort by
        # (mixing real pixel Y with a raw list-index fallback would
        # always put the undragged half first, wherever the dragged
        # sibling actually landed).
        baseline_positions = _markov_tree_layout(strategy)
        effective_positions = {**baseline_positions, **stored_positions}
        computed_positions = _markov_tree_layout(strategy, effective_positions)
        raw_ys = [y for _, y in computed_positions.values()] or [LAYOUT_START_Y]
        y_offset = y_cursor - min(raw_ys)

        def position_for(raw_id: str, default_x: float) -> tuple[float, float]:
            stored = stored_positions.get(raw_id)
            if stored is not None:
                return stored
            base_x, base_y = computed_positions.get(raw_id, (default_x - LAYOUT_X_SPACING, LAYOUT_START_Y))
            return (base_x + LAYOUT_X_SPACING, base_y + y_offset)

        root_x, root_y = decision_positions.get(root_id) or position_for(
            MARKOV_ROOT_ID, LAYOUT_START_X + LAYOUT_X_SPACING
        )
        nodes.append({
            "id": root_id, "x": root_x, "y": root_y, "kind": "root",
            "label": strategy.get("name") or strategy_id, "deletable": False,
            "cycle_label": f"_cycle = {int(document.get('cycles', 10))}",
            "cycle_editable": {"type": "model_cycles", "current": str(int(document.get("cycles", 600)))},
            "result_label": result_label,
        })
        edges.append({
            "id": f"{MARKOV_DECISION_ID}::{root_id}",
            "source": MARKOV_DECISION_ID,
            "target": root_id,
            "label": strategy.get("name") or strategy_id,
            "editable": {"type": "strategy_name", "current": strategy.get("name") or strategy_id},
        })
        root_ys.append(root_y)

        # promoted_transition_by_state: a state missing from it is
        # top-level (a real health state, drawn off the root below);
        # a state present in it is a canvas-created child of another
        # state, whose one real incoming edge is that transition --
        # skipped below when the parent's own outgoing transitions are
        # turned into leaves so it is never drawn twice.
        promoted_transition_by_state = _markov_promoted_transition_by_state(strategy)
        promoted_transition_ids: set[int] = {id(t) for t in promoted_transition_by_state.values()}

        # Cheap, resolution-free error flags for canvas highlighting
        # (highlight the exact field that's wrong instead of
        # only a generic banner) -- computed once per strategy here,
        # not per node/edge, and reused below. Only REAL states
        # (direct children of M) need their own Cost/Effect filled in
        # -- a non-real state has no Cost/Effect field of its own any
        # more (it is a single value, shown as Incre_$),
        # its one-time contribution lives entirely on its incoming
        # transition's Incre_$/Incre_E instead, which is never
        # "required" (unset just means zero contribution).
        missing_cost_ids = {sid for sid, s in states.items() if not s.get("canvas_parent") and "cost" not in s}
        missing_effect_ids = {sid for sid, s in states.items() if not s.get("canvas_parent") and "effect" not in s}
        prob_error_by_from_state = {
            from_id: _markov_local_probability_group_error(
                [t.get("probability") for t in transitions]
            )
            for from_id, transitions in outgoing_by_state.items()
        }
        top_level_initial_prob_error = _markov_local_probability_group_error([
            s.get("initial_prob", 0)
            for sid, s in states.items()
            if sid not in promoted_transition_by_state
        ])

        # Real validation errors for THIS strategy, reduced to the one
        # state id each is about -- node_id when the error already names
        # one (missing_transitions, unresolved_alias, negative_cost, ...),
        # else the leading state id off of field (missing_parameter and
        # the probability-group checks stash it there as "state_id" or
        # "state_id.cost"/"state_id.effect", always a real state id
        # since unknown_state is checked first). A group-level error with
        # neither (the two probability-sum-to-1 checks) has no single
        # node to point at -- that case is already covered visually by
        # prob_error_by_from_state/top_level_initial_prob_error above.
        strategy_blocking_result = blocking_results_by_id.get(strategy_id)
        blocking_error_state_ids: set[str] = set()
        if strategy_blocking_result is not None:
            for error in strategy_blocking_result.errors:
                error_state_id = error.node_id or (error.field.split(".", 1)[0] if error.field else None)
                if error_state_id:
                    blocking_error_state_ids.add(error_state_id)

        for state in states.values():
            state_id = state["id"]
            composite_state_id = f"{strategy_id}::{state_id}"
            node_owner[composite_state_id] = (strategy_id, state_id)
            outgoing = outgoing_by_state.get(state_id, [])
            node_kind = _markov_canvas_kind(state, outgoing)
            x, y = position_for(state_id, LAYOUT_START_X + LAYOUT_X_SPACING * 2)
            is_health_state = state_id not in promoted_transition_by_state
            # A nested chance node (not a direct child of root M) shows
            # no name on the canvas by default -- rule: only
            # terminal states and root-level chance states carry a
            # visible name there, to avoid cluttering a deep chain of
            # unnamed double-click branches. But once the user actually
            # renames one of these (e.g. via the Edit State side panel,
            # since a nested chance node has no visible label to click
            # on canvas), that custom name always shows -- otherwise a
            # renamed node is indistinguishable from every other blank
            # nested chance node, and a validation error referencing it
            # by its raw auto id (e.g. "chance_7") is untraceable back
            # to any node on the canvas.
            state_custom_name = state.get("name")
            has_custom_name = bool(state_custom_name) and state_custom_name != state_id
            show_node_label = node_kind != "chance" or is_health_state or has_custom_name
            node_label_text = (state.get("name") or state_id) if show_node_label else ""
            nodes.append({"id": composite_state_id, "x": x, "y": y, "kind": node_kind, "label": node_label_text, "deletable": True, "is_health_state": is_health_state, "has_error": state_id in missing_cost_ids or state_id in missing_effect_ids or state_id in blocking_error_state_ids, "num": state.get("num"), "show_num": show_state_numbers})

            promoted_transition = promoted_transition_by_state.get(state_id)
            if promoted_transition is not None:
                # Canvas child of another state: one real edge from that
                # parent state's own node, not from the root -- this is
                # what keeps a double-click chain looking like a tree
                # hanging off its parent instead of every generation
                # sprouting a second, parallel line straight back to M.
                parent_composite_id = f"{strategy_id}::{promoted_transition.get('from_state')}"
                parent_probability_text = value_text(promoted_transition.get("probability"))
                edge_annotations = _markov_edge_annotations(
                    strategy_id,
                    state_id,
                    state,
                    promoted_transition.get("label"),
                    {"strategy_id": strategy_id, "transition_index": _markov_transition_index(strategy, promoted_transition)},
                    transition=promoted_transition,
                    # A non-real (canvas-child) state has NO Cost/Effect
                    # of its own any more (it is a single value, shown as Incre_$ -- one single number, shown
                    # as Incre_$/Incre_E, not two separate rows that
                    # could silently double-count the same one-time
                    # cost). Its whole one-time contribution lives on
                    # THIS transition's own cost_increment/effect_increment
                    # (the existing Incre_$/Incre_E row below), edited
                    # from here or from the "Edit state" panel -- see
                    # the Edit State panel code for how it now edits
                    # THIS SAME transition instead of state["cost"]/
                    # state["effect"] for a non-real state.
                    include_state_reward=False,
                )
                edges.append({
                    "id": f"{parent_composite_id}::{composite_state_id}",
                    "source": parent_composite_id,
                    "target": composite_state_id,
                    "prob_label": f"p={parent_probability_text}" if parent_probability_text else "",
                    "editable": {
                        "type": "transition_probability",
                        "strategy_id": strategy_id,
                        "transition_index": _markov_transition_index(strategy, promoted_transition),
                        "current": parent_probability_text,
                    },
                    "prob_error": prob_error_by_from_state.get(promoted_transition.get("from_state"), False),
                    **edge_annotations,
                })
            else:
                initial_prob = state.get("initial_prob", 0)
                initial_prob_text = value_text(initial_prob)
                # initial_prob always holds a real value (states default to
                # 0.0, never left unset the way cost/effect can be), so its
                # "p=" label is always shown -- including p=0 -- instead of
                # only showing up once a state is given a nonzero starting
                # share of the cohort.
                # A top-level state's only real parent is the strategy
                # root -- its cycle-0 initial occupancy probability.
                # This must never be skipped just because the state ALSO
                # has transitions coming from other states in later
                # cycles (the normal shape of a real Markov model, e.g.
                # Healthy <-> Sick): those are drawn below as each SOURCE
                # state's own private leaf branch, never as a second edge
                # landing on this state's real node, so every node here
                # keeps exactly one parent (like the Decision Tree
                # canvas).
                edge_annotations = _markov_edge_annotations(
                    strategy_id,
                    state_id,
                    state,
                    state.get("entry_label"),
                    {"strategy_id": strategy_id, "state_id": state_id},
                )
                edges.append({
                    "id": f"{root_id}::{composite_state_id}",
                    "source": root_id,
                    "target": composite_state_id,
                    "prob_label": f"p={initial_prob_text}",
                    "editable": {
                        "type": "initial_prob",
                        "strategy_id": strategy_id,
                        "state_id": state_id,
                        "current": value_text(initial_prob),
                    },
                    "prob_error": top_level_initial_prob_error,
                    **edge_annotations,
                })

            occurrence_counts: dict[tuple[str, str], int] = {}
            for transition in outgoing:
                if id(transition) in promoted_transition_ids:
                    # Already drawn above as this target state's real
                    # incoming edge from its canvas parent -- drawing it
                    # again here would duplicate that child as a second,
                    # generic terminal leaf too.
                    continue
                to_state = transition.get("to_state")
                target_state = states.get(to_state)
                if target_state is None:
                    continue
                key = (state_id, to_state)
                occurrence_counts[key] = occurrence_counts.get(key, 0) + 1
                leaf_id = _markov_leaf_id(state_id, to_state, occurrence_counts[key])
                composite_leaf_id = f"{strategy_id}::{leaf_id}"
                node_owner[composite_leaf_id] = (strategy_id, None)
                # Maps to the REAL state this leaf triangle depicts
                # (to_state), not the source chance node it hangs off of --
                # a leaf is just a canvas pointer to a state already drawn
                # elsewhere, so clicking it must open THAT state in the
                # Edit State panel, not the state we're currently iterating.
                leaf_owner[composite_leaf_id] = f"{strategy_id}::{to_state}"
                leaf_transition[composite_leaf_id] = (strategy_id, _markov_transition_index(strategy, transition))
                leaf_x, leaf_y = position_for(leaf_id, LAYOUT_START_X + LAYOUT_X_SPACING * 3)
                nodes.append({"id": composite_leaf_id, "x": leaf_x, "y": leaf_y, "kind": "terminal", "label": target_state.get("name") or to_state, "deletable": False})

                probability_text = value_text(transition.get("probability"))
                edge_annotations = _markov_edge_annotations(
                    strategy_id,
                    to_state,
                    target_state,
                    transition.get("label"),
                    {"strategy_id": strategy_id, "transition_index": _markov_transition_index(strategy, transition)},
                    transition=transition,
                    include_state_reward=False,
                )
                edges.append({
                    "id": f"{composite_leaf_id}::edge",
                    "source": composite_state_id,
                    "target": composite_leaf_id,
                    "prob_label": f"p={probability_text}" if probability_text else "",
                    "editable": {
                        "type": "transition_probability",
                        "strategy_id": strategy_id,
                        "transition_index": _markov_transition_index(strategy, transition),
                        "current": probability_text,
                    },
                    "prob_error": prob_error_by_from_state.get(state_id, False),
                    **edge_annotations,
                })

        band_top = y_offset + min(raw_ys)
        band_bottom = y_offset + max(raw_ys)
        strategy_bands[strategy_id] = (band_top - LAYOUT_Y_SPACING / 2, band_bottom + LAYOUT_Y_SPACING / 2)
        y_cursor = band_bottom + LAYOUT_Y_SPACING * 2

    decision_x, decision_y = decision_positions.get(MARKOV_DECISION_ID) or (
        LAYOUT_START_X,
        sum(root_ys) / len(root_ys) if root_ys else LAYOUT_START_Y,
    )
    nodes.insert(0, {"id": MARKOV_DECISION_ID, "x": decision_x, "y": decision_y, "kind": "decision", "label": "", "deletable": False})

    st.session_state.markov_leaf_owner = leaf_owner
    st.session_state.markov_leaf_transition = leaf_transition
    st.session_state.markov_node_owner = node_owner
    st.session_state.markov_strategy_bands = strategy_bands
    return nodes, edges


def markov_flow_state() -> StreamlitFlowState:
    document = st.session_state.markov_document
    states = markov_state_map()
    outgoing_by_state = _markov_outgoing_by_state(document)
    computed_positions = _markov_tree_layout(document)
    leaf_owner: dict[str, str] = {}
    flow_nodes = []
    flow_edges = []

    def position_for(node_id: str, default: tuple[float, float]) -> tuple[float, float]:
        return st.session_state.markov_positions.get(node_id, computed_positions.get(node_id, default))

    root_background, root_border = MARKOV_NODE_COLOR
    root_x, root_y = position_for(MARKOV_ROOT_ID, (LAYOUT_START_X, LAYOUT_START_Y))
    flow_nodes.append(
        StreamlitFlowNode(
            MARKOV_ROOT_ID,
            (root_x, root_y),
            {"content": "M"},
            node_type="input",
            source_position="right",
            target_position="left",
            selectable=True,
            draggable=True,
            connectable=False,
            deletable=False,
            style={
                "background": root_background,
                "border": f"2px solid {root_border}",
                "color": "#ffffff",
                **MARKOV_NODE_SHAPE_STYLE,
            },
        )
    )

    for state in states.values():
        state_id = state["id"]
        outgoing = outgoing_by_state.get(state_id, [])
        node_kind = "chance" if outgoing else "terminal"
        background, border = NODE_COLORS[node_kind]
        x, y = position_for(state_id, (LAYOUT_START_X + LAYOUT_X_SPACING, LAYOUT_START_Y))
        flow_nodes.append(
            StreamlitFlowNode(
                state_id,
                (x, y),
                {"content": state.get("name") or state_id},
                node_type="default",
                source_position="right",
                target_position="left",
                selectable=True,
                draggable=True,
                connectable=True,
                deletable=True,
                style={
                    "background": background,
                    "border": f"2px solid {border}",
                    "color": "#172235",
                    **NODE_SHAPE_STYLE[node_kind],
                },
            )
        )

        root_label_parts = [state.get("name") or state_id]
        initial_prob = state.get("initial_prob", 0)
        if _clean(initial_prob).strip() not in ("", "0", "0.0"):
            root_label_parts.append(f"p={value_text(initial_prob)}")
        flow_edges.append(
            StreamlitFlowEdge(
                f"{MARKOV_ROOT_ID}::{state_id}",
                MARKOV_ROOT_ID,
                state_id,
                edge_type="smoothstep",
                label=" \u00b7 ".join(root_label_parts),
                label_show_bg=True,
                label_bg_style={"fill": "#ffffff", "fillOpacity": 0.92},
                style={"stroke": "#8290a6", "strokeWidth": 2},
            )
        )

        leaf_background, leaf_border = NODE_COLORS["terminal"]
        occurrence_counts: dict[tuple[str, str], int] = {}
        for transition in outgoing:
            to_state = transition.get("to_state")
            target_state = states.get(to_state)
            if target_state is None:
                continue
            key = (state_id, to_state)
            occurrence_counts[key] = occurrence_counts.get(key, 0) + 1
            leaf_id = _markov_leaf_id(state_id, to_state, occurrence_counts[key])
            leaf_owner[leaf_id] = state_id
            leaf_x, leaf_y = position_for(leaf_id, (LAYOUT_START_X + LAYOUT_X_SPACING * 2, LAYOUT_START_Y))
            flow_nodes.append(
                StreamlitFlowNode(
                    leaf_id,
                    (leaf_x, leaf_y),
                    {"content": target_state.get("name") or to_state},
                    node_type="default",
                    source_position="right",
                    target_position="left",
                    selectable=True,
                    draggable=True,
                    connectable=False,
                    deletable=False,
                    style={
                        "background": leaf_background,
                        "border": f"2px solid {leaf_border}",
                        "color": "#172235",
                        **NODE_SHAPE_STYLE["terminal"],
                    },
                )
            )
            leaf_label_parts = [target_state.get("name") or to_state]
            probability_text = value_text(transition.get("probability"))
            if probability_text:
                leaf_label_parts.append(f"p={probability_text}")
            flow_edges.append(
                StreamlitFlowEdge(
                    f"{leaf_id}::edge",
                    state_id,
                    leaf_id,
                    edge_type="smoothstep",
                    label=" \u00b7 ".join(leaf_label_parts),
                    label_show_bg=True,
                    label_bg_style={"fill": "#ffffff", "fillOpacity": 0.92},
                    style={"stroke": "#8290a6", "strokeWidth": 2},
                )
            )

    st.session_state.markov_leaf_owner = leaf_owner
    return StreamlitFlowState(
        flow_nodes,
        flow_edges,
        st.session_state.markov_selected_id,
        timestamp=st.session_state.markov_flow_timestamp,
    )


def mark_markov_flow_changed() -> None:
    """Tell the Markov canvas to reconcile a deliberate model edit."""

    st.session_state.markov_flow_timestamp += 1


def add_markov_state(
    state_id: str,
    name: str,
    cost: str,
    effect: str,
    initial_prob: str,
    is_absorbing: bool,
) -> str | None:
    states = markov_state_map()
    state_id = state_id.strip()
    if not state_id:
        return T["state_required"]
    if state_id in states:
        return T["state_exists"].format(id=state_id)
    new_state = {
        "id": state_id,
        "name": name.strip() or state_id,
        "cost": numeric_or_name(cost),
        "effect": numeric_or_name(effect),
        "initial_prob": numeric_or_name(initial_prob),
        "is_absorbing": is_absorbing,
    }
    markov_active_strategy().setdefault("states", []).append(new_state)
    st.session_state.markov_selected_id = state_id
    return None


def add_markov_quick_chance_states(strategy: dict[str, Any]) -> None:
    """Add two standalone chance states for the Markov canvas shortcut."""

    states = strategy.setdefault("states", [])
    existing_ids = {state["id"] for state in states}
    for _ in range(2):
        index = len(states) + 1
        state_id = f"chance_{index}"
        while state_id in existing_ids:
            index += 1
            state_id = f"chance_{index}"
        states.append(
            {
                "id": state_id,
                "name": state_id,
                "cost": 0.0,
                "effect": 0.0,
                "initial_prob": 0.0,
                "is_absorbing": False,
                "canvas_kind": "chance",
            }
        )
        strategy.setdefault("transitions", []).append(
            {"from_state": state_id, "to_state": state_id, "probability": "#"}
        )
        existing_ids.add(state_id)


def add_markov_canvas_state(
    strategy: dict[str, Any],
    child_kind: str,
    name: str | None = None,
    parent_raw_id: str | None = None,
) -> str:
    """Create one state from a Markov canvas action. parent_raw_id, when
    given, is the raw id of the node this one was created as a child of
    (a double-clicked chance state, or a right-click "add node" with a
    specific parent) -- stored as canvas_parent so _markov_tree_layout
    positions it one generation deeper instead of in the flat top-level
    state column."""

    states = strategy.setdefault("states", [])
    existing_ids = {state["id"] for state in states}
    base = re.sub(r"[^a-zA-Z0-9_]+", "_", (name or child_kind)).strip("_").lower() or child_kind
    state_id = base
    suffix = 1
    while state_id in existing_ids:
        suffix += 1
        state_id = f"{base}_{suffix}"
    states.append(
        {
            "id": state_id,
            "name": name or state_id,
            "initial_prob": 0.0,
            "is_absorbing": False,
            "canvas_kind": child_kind,
            "canvas_parent": parent_raw_id,
        }
    )
    return state_id


def _markov_add_new_strategy(document: dict[str, Any]) -> dict[str, Any]:
    """Create, append, and return a brand new empty strategy (its own
    Markov root/"M" node) on this document. Deliberately never stores a
    canvas position for its root -- markov_canvas_payload()'s own
    band-stacking layout places a strategy with no stored position in a
    fresh row below every existing strategy, instead of it needing to be
    hand-positioned here."""

    strategies = document.setdefault("strategies", [])
    existing_ids = {strategy["id"] for strategy in strategies}
    index = len(strategies) + 1
    strategy_id = f"strategy_{index}"
    while strategy_id in existing_ids:
        index += 1
        strategy_id = f"strategy_{index}"
    new_strategy = {"id": strategy_id, "name": f"Strategy {index}", "states": [], "transitions": []}
    strategies.append(new_strategy)
    return new_strategy


def adopt_markov_context_menu_nodes(flow_result: StreamlitFlowState) -> bool:
    """Adopt states created by React Flow's right-click menu into the model."""

    states = markov_state_map()
    new_flow_nodes = [
        node
        for node in flow_result.nodes
        if node.id not in states
        and node.id != MARKOV_ROOT_ID
        and not node.id.startswith("__leaf__")
        and "__cycle_label" not in node.id
    ]
    if not new_flow_nodes:
        return False
    for flow_node in new_flow_nodes:
        content = str(flow_node.data.get("content", "")).strip()
        label = content if content and content != "M" else ""
        safe_id = re.sub(r"[^a-zA-Z0-9_]+", "_", label).strip("_").lower()
        safe_id = safe_id or f"state_{len(states) + 1}"
        while safe_id in states:
            safe_id = f"{safe_id}_new"
        new_state = {
            "id": safe_id,
            "name": safe_id,
            "cost": 0.0,
            "effect": 0.0,
            "initial_prob": 0.0,
            "is_absorbing": False,
            "canvas_kind": "chance",
        }
        st.session_state.markov_document["states"].append(new_state)
        position = flow_node.position
        st.session_state.markov_positions[safe_id] = (position["x"], position["y"])
        st.session_state.markov_selected_id = safe_id
        states[safe_id] = new_state
    st.session_state.markov_flow_component_version += 1
    st.session_state.markov_flow_fitted = False
    mark_markov_flow_changed()
    return True


def remove_markov_canvas_nodes(flow_result: StreamlitFlowState) -> bool:
    """Apply state deletions made through the Markov canvas to the model."""

    states = markov_state_map()
    visible_ids = {node.id for node in flow_result.nodes if "__cycle_label" not in node.id}
    deleted_ids = set(states) - visible_ids
    if not deleted_ids:
        return False
    st.session_state.markov_document["states"] = [
        state for state in st.session_state.markov_document["states"] if state["id"] not in deleted_ids
    ]
    st.session_state.markov_document["transitions"] = [
        transition
        for transition in st.session_state.markov_document.get("transitions", [])
        if transition.get("from_state") not in deleted_ids and transition.get("to_state") not in deleted_ids
    ]
    st.session_state.markov_positions = {
        state_id: position
        for state_id, position in st.session_state.markov_positions.items()
        if state_id not in deleted_ids
    }
    if st.session_state.markov_selected_id in deleted_ids:
        st.session_state.markov_selected_id = None
    st.session_state.markov_flow_component_version += 1
    st.session_state.markov_flow_fitted = False
    mark_markov_flow_changed()
    return True


def markov_auto_layout() -> None:
    """Recompute a clean TreeAge-style tree layout for the Markov canvas:
    the Markov root on the left, one branch per state, and -- for states
    with outgoing transitions -- one further terminal leaf per
    transition on the right, standing for the state the cohort moves to
    next cycle. Same left-to-right depth/sibling-stacking convention as
    the decision tree's auto_layout().

    Unlike the old streamlit-flow-component-based canvas, the custom
    markov_canvas component has no pan/zoom camera to lose here -- it has
    no camera at all, only a fixed 1:1 SVG sized to fit its content -- so
    there's nothing to remount and no viewport that could jump when the
    layout is recomputed.
    """

    document = st.session_state.markov_document
    decision_positions: dict[str, tuple[float, float]] = {}
    strategy_positions: dict[str, dict[str, tuple[float, float]]] = {}
    root_y = LAYOUT_START_Y
    for strategy in document.get("strategies", []):
        strategy_id = strategy["id"]
        stored_positions = st.session_state.markov_positions.get(strategy_id, {})
        baseline_positions = _markov_tree_layout(strategy)
        effective_positions = {**baseline_positions, **stored_positions}
        computed = _markov_tree_layout(strategy, effective_positions)
        raw_values = list(computed.values()) or [(LAYOUT_START_X, LAYOUT_START_Y)]
        offset_y = root_y - min(y for _, y in raw_values)
        strategy_positions[strategy_id] = {}
        for raw_id, (x, y) in computed.items():
            if raw_id == MARKOV_ROOT_ID:
                continue
            strategy_positions[strategy_id][raw_id] = (
                x + LAYOUT_X_SPACING,
                y + offset_y,
            )
        strategy_root_id = _markov_strategy_root_id(strategy_id)
        root_state_y = computed.get(MARKOV_ROOT_ID, (LAYOUT_START_X, root_y))[1] + offset_y
        decision_positions[strategy_root_id] = (LAYOUT_START_X + LAYOUT_X_SPACING, root_state_y)
        root_y = max(y for _, y in raw_values) + offset_y + LAYOUT_Y_SPACING * 2
    decision_positions[MARKOV_DECISION_ID] = (
        LAYOUT_START_X,
        sum(y for x, y in decision_positions.values()) / len(decision_positions)
        if decision_positions else LAYOUT_START_Y,
    )
    st.session_state.markov_positions = {
        "__decision__": decision_positions,
        **strategy_positions,
    }
    st.session_state.markov_layout_reset_nonce = st.session_state.get("markov_layout_reset_nonce", 0) + 1
    mark_markov_flow_changed()


