@st.dialog("Batch run", width="large")
def _render_batch_dialog() -> None:
    """File > Batch run...: base case + each model's saved scenarios for many
    model files at once, results as one Excel workbook (see batch.py).
    Scenarios are the ones saved in each model's Sensitivity Analysis >
    Scenario analysis table."""

    import tempfile
    from io import BytesIO

    from heor_tree_engine import batch as _batch

    st.caption(
        "Runs the base case and the saved scenarios of every model file (Decision Tree / PSM, Markov, "
        "Microsimulation). NMA, DES and ABM files are skipped. Results: one Excel workbook."
    )
    uploads = st.file_uploader("Model files", type=["decide", "json"], accept_multiple_files=True, key="batch_uploads")
    folder = st.text_input("...or a folder containing model files", value="", key="batch_folder",
                           placeholder="/Users/you/Documents/DECIDE models")
    cores = os.cpu_count() or 1
    workers = int(st.number_input("Processes (cores)", min_value=1, max_value=max(cores, 1), value=min(cores, 4),
                                  step=1, key="batch_workers", help=f"This computer has {cores} cores."))
    if st.button("Run batch", type="primary", key="batch_run"):
        with tempfile.TemporaryDirectory() as tmp:
            paths = []
            for upload in uploads or []:
                target = os.path.join(tmp, os.path.basename(upload.name))
                with open(target, "wb") as handle:
                    handle.write(upload.getvalue())
                paths.append(target)
            if folder.strip():
                paths.extend(_batch.collect_files([folder.strip()]))
            if not paths:
                st.warning("Add model files or a folder first.")
            else:
                with st.spinner(f"Running {len(paths)} file(s)..."):
                    outcomes = _batch.run_batch(paths, workers)
                buffer = BytesIO()
                _batch.write_excel(outcomes, buffer)
                st.session_state["batch_result"] = (outcomes, buffer.getvalue())
    saved = st.session_state.get("batch_result")
    if saved:
        outcomes, workbook = saved
        st.download_button(
            "Download Excel results", workbook, "decide-batch-results.xlsx",
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", key="batch_download",
        )
        st.dataframe(
            pd.DataFrame([{"File": o.path, "Type": o.kind or "-", "Status": o.status, "Rows": len(o.rows),
                           "Messages": " | ".join(o.messages)} for o in outcomes]),
            use_container_width=True, hide_index=True,
        )
        rows = [row for o in outcomes for row in o.rows]
        if rows:
            st.dataframe(pd.DataFrame(rows, columns=list(_batch.RESULT_COLUMNS)), use_container_width=True, hide_index=True)



def _strategy_comparison_rows(T, strategy_results, cost_symbol, cost_decimals, effect_symbol, effect_decimals):
    """Rows of the Base-case "Strategy comparison" table.

    Strategies are ordered by cost and each is compared with the previous
    NON-dominated strategy (not just the row above it), so a dominated strategy
    never becomes the comparator of the next one; extended dominance is flagged
    too.  See heor_tree_engine.icer.incremental_analysis."""

    from heor_tree_engine.icer import incremental_analysis

    info = {id(pair[1]): pair[0] for pair in strategy_results}
    analysis = incremental_analysis((id(pair[1]), pair[1].total_cost, pair[1].total_effect) for pair in strategy_results)
    results_by_key = {id(pair[1]): pair for pair in strategy_results}
    labels = {
        "dominated": T["dominated"],
        "extended_dominated": T.get("extended_dominated", "Extendedly dominated"),
    }
    rows = []
    for item in analysis:
        strategy, result = results_by_key[item.strategy_id]
        if item.status == "reference":
            icer_text = "-"
        elif item.icer is not None:
            icer_text = f"{item.icer:,.{cost_decimals}f}"
        else:
            icer_text = labels.get(item.status, T["dominated"])
        rows.append({
            T["strategy_name"]: strategy.get("name") or strategy.get("id", ""),
            f"{T['total_cost']} ({cost_symbol})": f"{result.total_cost:,.{cost_decimals}f}",
            f"{T['total_effect']} ({effect_symbol})": f"{result.total_effect:,.{effect_decimals}f}",
            T["incremental_cost"]: f"{item.incremental_cost:,.{cost_decimals}f}" if item.incremental_cost is not None else "-",
            T["incremental_effect"]: f"{item.incremental_effect:,.{effect_decimals}f}" if item.incremental_effect is not None else "-",
            f"{T['icer']} ({cost_symbol}/{effect_symbol})": icer_text,
        })
    return rows


@contextmanager
def _setting_panel(name: str, title: str):
    """Sidebar section that is an expander in the browser, but in the desktop
    app lives behind the native Setting menu and opens as a centred dialog.
    The body always runs (so widgets/state behave exactly as before); when
    closed the container is simply hidden."""
    if not DESKTOP_MODE:
        with st.expander(title, expanded=False):
            yield
        return
    is_open = st.session_state.get("_setting_open") == name
    cls = f"div.st-key-setting_{name}"
    css = f"{cls}{{display:none !important;}}"
    if is_open:
        css = f"""
        section[data-testid="stSidebar"], section[data-testid="stSidebar"] > div {{
            transform: none !important; will-change: auto !important; filter: none !important;
            contain: none !important; perspective: none !important;
        }}
        {cls} {{
            display: block !important; position: fixed !important; top: 50% !important; left: 50% !important;
            transform: translate(-50%, -50%) !important; width: min(920px, 88vw) !important;
            max-height: 86vh !important; overflow-y: auto !important; z-index: 1000002 !important; visibility: visible !important;
            background: #ffffff; border: 1px solid #1d4f9b; border-radius: 10px; padding: 20px 30px 26px 30px; box-sizing: border-box;
            box-shadow: 0 0 0 100vmax rgba(15, 30, 60, 0.45), 0 12px 40px rgba(0,0,0,0.35);
        }}
        {cls} [data-baseweb="select"] > div, {cls} [data-baseweb="input"], {cls} [data-baseweb="base-input"],
        {cls} [data-baseweb="textarea"], {cls} div[data-testid="stNumberInputContainer"] {{ background: #eceff4 !important; border-color: #cfd6e2 !important; }}
        {cls} [data-baseweb="select"] > div, {cls} input {{ color: #1f2a3a !important; }}
        {cls} input, {cls} textarea {{ background: #eceff4 !important; }}
        """
    st.markdown(f"<style>{css}</style>", unsafe_allow_html=True)
    with st.container(key=f"setting_{name}"):
        if is_open:
            head, close = st.columns([14, 1], vertical_alignment="center")
            head.markdown(f"### {title}")
            if close.button("✕", key=f"setting_{name}_close_btn", help="Close"):
                st.session_state._setting_open = None
                st.rerun()
        yield


def _export_panel(key: str):
    """Export-code panel: a bordered box in the browser's sidebar; in the desktop
    app it is a centred dialog opened from Setting > Export code."""
    if DESKTOP_MODE:
        return _setting_panel("export", "Export code")
    return st.container(key=key, border=True)


def _state_space_heading(label: str, document: dict[str, Any]) -> None:
    """'StateSpace' heading; in the desktop app the model's note (e.g. 'Adapted from ...')
    sits right beside it instead of above the toolbar."""
    note = document.get("note") if isinstance(document, dict) else None
    if DESKTOP_MODE and note:
        head_col, note_col = st.columns([1, 5], vertical_alignment="center")
        head_col.subheader(label)
        note_col.caption(str(note))
    else:
        st.subheader(label)


def render_top_bar(T: dict[str, str]) -> None:
    """Small dark-blue contact strip flush against the very top of the page.

    The "About us" label is a real st.button that spans the FULL bar (not
    just the label's own text width): st.button() is called with
    use_container_width=True, which is what actually makes Streamlit's
    own stButton wrapper div stretch to 100% instead of shrinking to
    fit the label -- every earlier attempt styled the <button> tag or
    its wrapper with CSS width:100% alone, which had no effect because
    that wrapper stays fit-content-sized unless use_container_width=True
    is passed to st.button() itself; CSS can't override that. Once the
    wrapper is actually full width, display:flex; justify-content:flex-end
    on the <button> tag pushes the label to the bar's right edge, exactly
    like the original plain-text bar did via text-align:right."""

    st.markdown(
        f"""
        <style>
        div.block-container {{
            padding-top: 2.4rem;
        }}
        /* Keep a "Settings" label attached to the sidebar's collapse/expand
           control, so it's visible in both states. Confirmed by inspecting
           the live DOM: Streamlit 1.38 uses TWO different testids, not one
           reused element -- stSidebarCollapseButton (a <div>, the "<<" icon
           inside the sidebar header when expanded) and
           stExpandSidebarButton (a <button>, the floating ">>" icon in the
           main area when collapsed). */
        [data-testid="stSidebarCollapseButton"],
        [data-testid="stExpandSidebarButton"] {{
            display: flex !important;
            align-items: center !important;
            gap: 6px !important;
            width: auto !important;
            min-width: auto !important;
            overflow: visible !important;
        }}
        [data-testid="stSidebarCollapseButton"]::after,
        [data-testid="stExpandSidebarButton"]::after {{
            content: "{T['settings_title']}";
            font-weight: 600;
            font-size: 0.95rem;
            color: #1d4f9b;
            white-space: nowrap;
            margin-left: 4px;
        }}
        </style>
        """,
        unsafe_allow_html=True,
    )
    st.markdown(
        """
        <style>
        div[class*="st-key-topbar_about_bar"] {
            background-color:#1d4f9b;
            border-radius:6px 6px 0 0;
            margin-bottom:0;
            overflow:hidden;
        }
        div[class*="st-key-topbar_about_bar"] [data-testid="stVerticalBlock"] {
            gap: 0 !important;
            padding: 0 !important;
        }
        div[class*="st-key-topbar_about_bar"] [data-testid="stElementContainer"] {
            width: 100% !important;
            padding: 0 !important;
            margin: 0 !important;
        }
        /* The button IS the bar: full width, its own <button> tag made a
           flex row with justify-content:flex-end so the label sits at
           the right edge, exactly like the original plain-text bar did
           via text-align:right.

           Streamlit wraps every st.button in a stButton div that is only
           as wide as the label ("fit-content") unless the button itself
           is created with use_container_width=True -- without that, this
           wrapper never actually reaches 100% width, so justify-content
           on the inner <button> has no room to push the label anywhere
           and it just sits at its natural (left) position. Forcing the
           wrapper's own width here is a belt-and-suspenders backup for
           that same use_container_width=True passed below. */
        div[class*="st-key-topbar_about_bar"] [data-testid="stButton"],
        div[class*="st-key-topbar_about_bar"] [data-testid="stButton"] > div {
            width: 100% !important;
        }
        div[class*="st-key-topbar_about_button"] {
            width: 100% !important;
        }
        div.st-key-topbar_about_button button {
            display: flex !important;
            justify-content: flex-end !important;
            align-items: center !important;
            width: 100% !important;
            background:#1d4f9b !important;
            border:none !important;
            border-radius:0 !important;
            color:#ffffff !important;
            font-size:0.9rem !important;
            font-weight:400 !important;
            padding:6px 16px !important;
            min-height:0 !important;
            height:auto !important;
            line-height:1.2 !important;
            box-shadow:none !important;
            white-space: nowrap !important;
        }
        /* Streamlit centers a full-width button's own label wrapper
           (the div right inside <button>, holding the markdown-rendered
           <p>) -- that div carries its OWN justify-content:center, which
           wins over the flex-end set on the outer <button> above because
           it's a separate flex box one level down, not something the
           parent's justify-content can reach past. Every direct child of
           the button (whatever Streamlit names it in this version) is
           forced flex/flex-end/full-width here too, and the <p> itself
           gets text-align:right as a plain-CSS fallback that works
           regardless of any flex nesting. */
        div.st-key-topbar_about_button button > div,
        div.st-key-topbar_about_button button [data-testid="stMarkdownContainer"] {
            display: flex !important;
            justify-content: flex-end !important;
            width: 100% !important;
        }
        div.st-key-topbar_about_button button p {
            text-align: right !important;
            width: 100% !important;
            margin: 0 !important;
        }
        div.st-key-topbar_about_button button:hover {
            color:#ffffff !important;
            text-decoration: underline;
            background:#1d4f9b !important;
        }
        div.st-key-topbar_about_button button:focus:not(:active) {
            color:#ffffff !important;
            background:#1d4f9b !important;
            box-shadow:none !important;
        }
        </style>
        """,
        unsafe_allow_html=True,
    )
    with st.container(key="topbar_about_bar"):
        if st.button(
            f"| {T['topbar_about_label']}",
            key="topbar_about_button",
            use_container_width=True,
        ):
            _render_about_us_dialog()
        st.markdown(
            """
            <div style="height:28px; width:100%; display:block; margin-top:0;
                        background: linear-gradient(135deg, #eaf3fc 0%, #dcebfa 100%);"></div>
            """,
            unsafe_allow_html=True,
        )


