# Shared visual for the collapsed-bar state of any Run/SA/PSA/Dashboard
# panel (Tree/Markov/Microsim all use the "<anchor_key>_bar" container-key
# convention from _panel_collapsed_bar() above) -- a substring selector so
# one rule covers all of them regardless of which app is active.
st.markdown(
    """
    <style>
    div[class*="st-key-"][class*="_panel_anchor_bar"] {
        background: #eef2f9;
        border: 1px solid #b7d0f4;
        border-radius: 8px;
        padding: 10px 14px;
        margin-bottom: 8px;
    }
    /* Mac-style traffic-light dots for the collapse/close/expand trio on
       every Run/SA/PSA/Dashboard panel (Tree/Markov/Microsim), styled by
       button-key suffix so one rule set covers all 12 instances. Colors:
       blue (close), orange (collapse), green
       (expand) -- same round-dot layout as macOS window controls,
       recolored to the app's own palette. */
    div[class*="st-key-"][class*="_collapse_btn"] button,
    div[class*="st-key-"][class*="_close_btn"] button,
    div[class*="st-key-"][class*="_expand_btn"] button {
        width: 26px !important;
        height: 26px !important;
        min-width: 26px !important;
        min-height: 26px !important;
        padding: 0 !important;
        border-radius: 50% !important;
        border: none !important;
        line-height: 1 !important;
        font-size: 15px !important;
        font-weight: 700 !important;
        color: #ffffff !important;
        box-shadow: 0 1px 2px rgba(0, 0, 0, 0.25) !important;
    }
    div[class*="st-key-"][class*="_close_btn"] button {
        background: #16a34a !important;
    }
    div[class*="st-key-"][class*="_close_btn"] button:hover {
        background: #15803d !important;
    }
    div[class*="st-key-"][class*="_collapse_btn"] button {
        background: #f97316 !important;
    }
    div[class*="st-key-"][class*="_collapse_btn"] button:hover {
        background: #ea580c !important;
    }
    div[class*="st-key-"][class*="_expand_btn"] button {
        background: #2563eb !important;
    }
    div[class*="st-key-"][class*="_expand_btn"] button:hover {
        background: #1d4ed8 !important;
    }
    /* Pin the collapse+close dots to the panel's top-right corner and make
       them sit right next to each other, regardless of the panel's actual
       rendered width -- st.columns() ratios alone left a big proportional
       gap here (the "spacer" column's own leftover space pushed the 2nd
       dot away from the 1st). Scoped to the "_dots" wrapper container so
       this never touches any other st.columns() layout in the app. */
    div[class*="st-key-"][class*="_dots"] [data-testid="stHorizontalBlock"] {
        justify-content: flex-end !important;
        gap: 6px !important;
    }
    div[class*="st-key-"][class*="_dots"] [data-testid="column"],
    div[class*="st-key-"][class*="_dots"] [data-testid="stColumn"] {
        flex: 0 0 auto !important;
        width: fit-content !important;
        min-width: fit-content !important;
    }
    </style>
    """,
    unsafe_allow_html=True,
)

st.markdown(
    """
    <style>
    /* Sensitivity-analysis input list: alternate white / light-grey rows */
    div[class*="st-key-sa_row_1_"] { background: #f1f4f9; border-radius: 8px; padding: 8px 8px; }
    div[class*="st-key-sa_row_0_"] { background: #ffffff; border-radius: 8px; padding: 8px 8px; }
    /* rows touch each other: no gap between the white and grey bands */
    div[data-testid="stVerticalBlock"]:has(> div[class*="st-key-sa_row_"]), div[data-testid="stVerticalBlock"]:has(> * > div[class*="st-key-sa_row_"]) { gap: 0 !important; }
    div[data-testid="stElementContainer"]:has(> div[class*="st-key-sa_row_"]) { margin: 0 !important; }
    div[class*="st-key-sa_row_"] [data-testid="stVerticalBlock"] { gap: 0 !important; }
    </style>
    """,
    unsafe_allow_html=True,
)

_staging_models_gate, _staging_source = _staging_config()
if not DESKTOP_MODE:  # the desktop app shows neither the build line nor the staging banner
    st.caption(
        f"Build {STAGING_BUILD_TAG} | model filter: "
        + (", ".join(sorted(_staging_models_gate)) + f" (from {_staging_source})" if _staging_models_gate is not None else f"off ({_staging_source})")
    )
if _staging_models_gate is not None and not DESKTOP_MODE:
    st.info(
        "Staging trial build: for testing only, not for policy or reimbursement decisions. "
        "Please save your model as a JSON file to your computer; models are not stored on the server."
    )
    if st.session_state.model_type is not None and st.session_state.model_type not in _staging_models_gate:
        st.session_state.model_type = None

# ---------------------------------------------------------------------------
# Desktop app: the native menu bar (packaging/launcher.py) sends File commands
# (new / open / save / save_as) by writing a small JSON file that this poller
# picks up; the launcher reads state.json to know whether the open model
# already has a file (Save vs Save As).
# ---------------------------------------------------------------------------
DESKTOP_COMMAND_FILE = os.environ.get("DECIDE_COMMAND_FILE", "")
DESKTOP_STATE_FILE = os.environ.get("DECIDE_STATE_FILE", "")
_DESKTOP_KINDS = ("tree", "markov", "psm", "microsim", "des", "abm", "nma")


def _desktop_kinds() -> tuple[str, ...]:
    return _DESKTOP_KINDS + tuple(_OPTIONAL_EDITORS)


def _desktop_wid() -> str:
    """Id of this window/tab (the launcher opens each as .../?w=<id>); commands and
    state files are per window so menu actions only reach the tab being viewed."""
    wid = st.session_state.get("desktop_wid")
    if not wid:
        wid = str(st.query_params.get("w") or "w1")
        st.session_state.desktop_wid = wid
    return wid


def _desktop_cmd_path() -> str:
    if not DESKTOP_COMMAND_FILE:
        return ""
    return os.path.join(os.path.dirname(DESKTOP_COMMAND_FILE), f"command-{_desktop_wid()}.json")


def _desktop_state_path() -> str:
    if not DESKTOP_STATE_FILE:
        return ""
    return os.path.join(os.path.dirname(DESKTOP_STATE_FILE), f"state-{_desktop_wid()}.json")


@st.fragment(run_every=1.0)
def _desktop_command_poller() -> None:
    path = _desktop_cmd_path()
    if not path or not os.path.exists(path):
        return
    try:
        with open(path, encoding="utf-8") as handle:
            command = json.load(handle)
    except (OSError, ValueError):
        command = None
    try:
        os.remove(path)
    except OSError:
        pass
    if isinstance(command, dict) and command.get("cmd"):
        st.session_state.desktop_command = command
        st.rerun()


def _desktop_files_for(kind: str | None):
    factories = {
        "markov": _markov_model_files, "microsim": _microsim_model_files, "psm": _psm_model_files,
        "des": _des_model_files, "abm": _abm_model_files,
    }
    if kind in factories:
        return factories[kind]()
    if kind in _OPTIONAL_EDITORS:
        return _OPTIONAL_EDITORS[kind]["model_files"]()
    if kind == "nma":
        from nma_editor import _nma_model_files

        return _nma_model_files()
    return None


def _desktop_current_path(kind: str | None) -> str | None:
    if kind == "tree":
        return st.session_state.get("tree_current_path")
    files = _desktop_files_for(kind)
    return st.session_state.get(files._k("current")) if files is not None else None


def _desktop_is_dirty(kind: str | None) -> bool:
    """Unsaved changes in the open model? (the launcher asks before closing a tab)"""
    try:
        if kind == "tree":
            saved_fp = st.session_state.get("tree_saved_fp", _tree_fingerprint(TREE_START_DOCUMENT))
            return _tree_fingerprint(st.session_state.document) != saved_fp
        files = _desktop_files_for(kind) if kind in _desktop_kinds() else None
        return bool(files is not None and files.is_dirty())
    except Exception:  # noqa: BLE001 - never block closing because of a state check
        return False


def _desktop_write_state() -> None:
    kind = st.session_state.get("model_type")
    payload = json.dumps({
        "model_type": kind,
        "current": _desktop_current_path(kind) if kind in _desktop_kinds() else None,
        "dirty": _desktop_is_dirty(kind),
    })
    if st.session_state.get("_desktop_state_written") == payload:
        return
    try:
        _state_path = _desktop_state_path()
        os.makedirs(os.path.dirname(_state_path), exist_ok=True)
        with open(_state_path, "w", encoding="utf-8") as handle:
            handle.write(payload)
        st.session_state._desktop_state_written = payload
    except OSError:
        pass


_DESKTOP_KIND_LABELS = {
    "tree": "Decision tree", "markov": "Markov model", "psm": "Partitioned survival model",
    "microsim": "Microsimulation", "des": "Discrete event simulation", "abm": "Agent-based model",
    "nma": "Network meta-analysis",
}


def _desktop_kind_labels() -> dict[str, str]:
    return {**_DESKTOP_KIND_LABELS, **{k: e["menu_label"] for k, e in _OPTIONAL_EDITORS.items()}}


def _desktop_guess_kind(path: str) -> tuple[str | None, bool]:
    """(kind, sure). Sure only when the file name starts with a model-type name
    (default names are '<kind>-model.decide') or the content is clearly NMA."""
    base = os.path.basename(path).lower()
    for k in _DESKTOP_KIND_LABELS:
        if base.startswith(k):
            return k, True
    try:
        with open(path, encoding="utf-8") as handle:
            doc = json.load(handle)
    except (OSError, ValueError):
        return None, False
    if not isinstance(doc, dict):
        return None, False
    if "studies" in doc or "analyses" in doc or "treatments" in doc:
        return "nma", True
    for _kind, _entry in _OPTIONAL_EDITORS.items():
        if _entry["detect"](doc):
            return _kind, True
    if "cycles" in doc:
        return "markov", False
    if "dashboard_items" in doc:
        return "psm", False
    return "tree", False


def _desktop_open_file(kind: str, path: str) -> None:
    allowed = _staging_allowed_models()
    if allowed is not None and kind not in allowed:
        st.toast(f"{_desktop_kind_labels().get(kind, kind)} is not available in this build.", icon=":material/info:")
        return
    st.session_state.model_type = kind
    _desktop_handle_command({"cmd": "open", "path": path})


@st.dialog("Open model")
def _desktop_choose_kind_dialog(path: str, guess: str | None) -> None:
    st.write(f"What type of model is **{os.path.basename(path)}**?")
    kinds = list(_desktop_kind_labels())
    choice = st.selectbox(
        "Model type", kinds, index=kinds.index(guess) if guess in kinds else 0,
        format_func=lambda k: _desktop_kind_labels()[k], key="desktop_open_kind_choice",
    )
    if st.button("Open", type="primary", key="desktop_open_kind_ok"):
        st.session_state.desktop_command = {"cmd": "open_typed", "path": path, "model": choice}
        st.rerun()


def _desktop_open_any(path: str | None) -> None:
    if not path:
        return
    kind, sure = _desktop_guess_kind(path)
    if kind and sure:
        _desktop_open_file(kind, path)
    else:
        _desktop_choose_kind_dialog(path, kind)


def _desktop_handle_command(command: dict[str, Any]) -> None:
    kind = st.session_state.get("model_type")
    name = command.get("cmd")
    path = command.get("path")
    if name == "goto":  # Go menu: switch editor (None = model picker)
        target = command.get("model")
        allowed = _staging_allowed_models()
        if target is None or allowed is None or target in allowed:
            st.session_state.model_type = target
        return
    if name == "about":
        _render_about_us_dialog()
        return
    if name == "batch":
        _render_batch_dialog()
        return
    if name == "open_any":
        _desktop_open_any(path)
        return
    if name == "open_typed":
        if path and command.get("model") in _DESKTOP_KIND_LABELS:
            _desktop_open_file(command["model"], path)
        return
    if name == "language":
        code = command.get("model")
        names = {v: k for k, v in LANGUAGES.items()}
        if code in names:
            st.session_state.language = code
            for _k in [k for k in st.session_state.keys() if str(k).endswith("language_choice")]:
                st.session_state[_k] = names[code]
            st.rerun()
        return
    if name == "setting":
        panel = command.get("model")
        if kind not in _desktop_kinds():
            st.toast("Open a model first.", icon=":material/info:")
        elif panel == "nma" and kind != "nma":
            st.toast("NMA settings apply to Network Meta-Analysis models only.", icon=":material/block:")
        elif panel != "nma" and kind == "nma":
            st.toast("Not applicable for NMA.", icon=":material/block:")
        elif str(panel).startswith("tree_") and kind != "tree":
            st.toast("These tools apply to Decision Tree models only.", icon=":material/block:")
        elif str(panel).startswith("psm_") and kind != "psm":
            st.toast("These tools apply to PSM models only.", icon=":material/block:")
        elif panel == "node_numbers":
            if kind == "tree":
                st.session_state.tree_show_node_numbers = not bool(st.session_state.get("tree_show_node_numbers", False))
                st.rerun()
            elif kind in ("markov", "microsim", "abm", "psm", "des"):
                # same switch as the "Show node numbers" toggle under the canvas (shared by these editors)
                st.session_state.show_state_numbers = not bool(st.session_state.get("show_state_numbers", False))
                st.rerun()
            else:
                st.toast("Node numbers are not available for this model type.", icon=":material/info:")
        elif panel == "nma":
            st.session_state._setting_open = "nma"
        elif panel == "calibration":
            if f"{kind}_calibration_open" in st.session_state or kind in ("tree", "markov", "psm", "microsim", "des"):
                st.session_state[f"{kind}_calibration_open"] = True
                st.session_state[f"{kind}_calibration_collapsed"] = False
                st.session_state.panel_scroll_target = f"{kind}_calibration_panel_anchor"
        elif panel == "export" and kind not in ("tree", "markov", "psm", "microsim"):
            st.toast("Export code is not available for this model type yet.", icon=":material/info:")
        else:
            st.session_state._setting_open = panel
        return
    if kind not in _desktop_kinds():
        st.toast("Open a model editor first - File commands act on the open model.", icon=":material/info:")
        return
    if name == "new":
        if kind in _CLEAR_MODEL_HANDLERS:
            _render_clear_model_confirm_dialog(kind)
        else:
            st.toast("New model is not available for this editor yet.", icon=":material/info:")
        return
    if name == "report":
        # File > Export report...: the Word/Excel report buttons sit at the bottom of
        # the base-case results window, so open (= run) that window for this model.
        prefix = {"tree": "", "markov": "markov_", "psm": "psm_", "microsim": "microsim_",
                  **{k: e["report_prefix"] for k, e in _OPTIONAL_EDITORS.items()}}.get(kind)
        if prefix is None:
            st.toast("Export report is available for " + ", ".join(["Decision Tree", "Markov", "PSM", "Microsimulation",
                     *[e["menu_label"] for e in _OPTIONAL_EDITORS.values()]]) + " models.",
                     icon=":material/info:")
        else:
            st.session_state[f"{prefix}results_open"] = True
            st.session_state[f"{prefix}results_collapsed"] = False
            st.session_state.panel_scroll_target = f"{prefix}results_panel_anchor"
            st.toast(_OPTIONAL_EDITORS[kind]["report_toast"] if kind in _OPTIONAL_EDITORS
                     else "Base case results opened. Use the Technical Documentation Report buttons at the bottom.",
                     icon=":material/description:")
        return
    if kind == "tree":
        if name == "save":
            _tree_cb_save()
        elif name == "save_as" and path:
            _tree_write_model(path)
        elif name == "open" and path:
            st.session_state.tree_models_dir_input = os.path.dirname(path)
            st.session_state.tree_open_choice = os.path.basename(path)
            _tree_cb_open_saved()
        message = st.session_state.pop("tree_file_message", None)
    else:
        files = _desktop_files_for(kind)
        if name == "save":
            files.save_current()
        elif name == "save_as" and path:
            files.save_to(path)
        elif name == "open" and path:
            files.open_path(path)
        message = st.session_state.pop(files._k("message"), None)
    if message:
        level, text = message
        st.toast(text, icon=":material/check_circle:" if level == "success" else ":material/error:")


if DESKTOP_MODE:
    _desktop_wid()
    _open_param = st.query_params.get("open")
    if _open_param and not st.session_state.get("_desktop_open_param_done"):
        st.session_state._desktop_open_param_done = True
        st.session_state.desktop_command = {"cmd": "open_any", "path": str(_open_param)}
        try:
            del st.query_params["open"]
        except Exception:  # noqa: BLE001
            pass
    _desktop_command_poller()
    _pending_desktop_command = st.session_state.pop("desktop_command", None)
    if _pending_desktop_command:
        _desktop_handle_command(_pending_desktop_command)
    _desktop_write_state()
